import {parse, type DefaultTreeAdapterTypes} from "parse5";
import type {ProofAssessmentCitation, ProofCriterion} from "./contracts.ts";
import {normalizeExactCopyWhitespace as normalized} from "./exact-copy-directive.ts";

type Node = DefaultTreeAdapterTypes.Node;
type Element = DefaultTreeAdapterTypes.Element;
const element = (node: Node): node is Element => "tagName" in node;
const INERT = new Set(["script", "style", "template", "noscript", "textarea", "iframe", "xmp", "noembed", "noframes", "plaintext"]);
// Only a complete unquoted, non-numeric content-title statement is admitted.
// Exact/verbatim directives, another obligation and unfamiliar grammar do not
// match. The generated metadata title must add no separate requirement.
const REQUIREMENT = /^The ([a-z][a-z0-9-]{0,39}) page content must contain the article title ([A-Za-z]+(?: [A-Za-z]+){2,39})\.?$/u;
const NEUTRAL_TITLE = /^(?:Manual requirement|Original requirement|人工要求|原始需求) [1-9]\d?$/u;

/** A negative guard only. A complete quoted direct-text h1 whose ASCII word
 * sequence differs solely by one ', and ' does not establish a definite
 * content defect. This never establishes compliance or semantic equivalence. */
export function hasUnestablishedArticleTitleCommaChange(criterion: ProofCriterion, files: Record<string, string>, citations: readonly ProofAssessmentCitation[]): boolean {
  const requirement = REQUIREMENT.exec(criterion.source.trim());
  if (!requirement || !NEUTRAL_TITLE.test(criterion.title.trim()) || citations.length !== 1) return false;
  const matching = Object.keys(files).filter(file => file.split("/").at(-1) === `${requirement[1]}.html`);
  if (matching.length !== 1 || citations[0].file !== matching[0]) return false;
  const file = matching[0], source = files[file], citation = citations[0];
  if (!Number.isSafeInteger(citation.start) || !Number.isSafeInteger(citation.end) || citation.start < 0 || citation.end > source.length
    || source.slice(citation.start, citation.end) !== citation.excerpt) return false;
  let issue = false, visits = 0;
  const document = parse(source, {sourceCodeLocationInfo: true, scriptingEnabled: true,
    onParseError: error => {if (error.code !== "missing-doctype") issue = true;}});
  const headings: Element[] = [], stack: {node: Node; depth: number}[] = [{node: document, depth: 0}];
  while (stack.length) {
    const {node, depth} = stack.pop()!;
    if (++visits > 50_000 || depth > 512) return false;
    if (element(node)) {
      if (node.namespaceURI !== "http://www.w3.org/1999/xhtml" || INERT.has(node.tagName)) continue;
      if (node.tagName === "h1") headings.push(node);
    }
    if ("childNodes" in node) for (let i = node.childNodes.length - 1; i >= 0; i--) stack.push({node: node.childNodes[i], depth: depth + 1});
  }
  if (issue || headings.length !== 1) return false;
  const heading = headings[0], location = heading.sourceCodeLocation;
  if (location?.startTag?.startOffset !== citation.start || location?.endTag?.endOffset !== citation.end
    || heading.childNodes.length !== 1 || heading.childNodes[0].nodeName !== "#text") return false;
  const text = heading.childNodes[0] as DefaultTreeAdapterTypes.TextNode, span = text.sourceCodeLocation;
  // Entity or inline variants remain outside this bounded rule; no rewriting
  // or reserialising source, quotation offsets or required wording occurs.
  if (!span || source.slice(span.startOffset, span.endOffset) !== text.value) return false;
  const actual = normalized(text.value), comma = actual.indexOf(", and ");
  return comma >= 0 && actual.indexOf(",") === comma && actual.lastIndexOf(",") === comma
    && actual.replace(", and ", " and ") === requirement[2];
}

import {parse, type DefaultTreeAdapterTypes} from "parse5";
import type {ProofAssessmentCitation} from "./contracts.ts";
import {DomainError} from "./domain.ts";
import {AssessmentResponseError} from "./assessment-response.ts";
import {ASSESSMENT_ITEM_CITATION_LIMIT} from "./assessment-limits.ts";
import {assertStaticPath, staticFileKind, STATIC_RESOURCE_LIMITS} from "./static-resources.ts";

export type AssessmentCitationCatalogEntry = ProofAssessmentCitation & {id: string};
export type AssessmentCitationCatalog = {
  version: "source-citation-catalog-v1";
  catalogId: string;
  entries: AssessmentCitationCatalogEntry[];
};
export type Catalog = AssessmentCitationCatalog;
export const ASSESSMENT_CITATION_CATALOG_LIMITS = {
  windowUnits: 400, excerptUnits: 500, entries: 1_536, serializedBytes: 384 * 1024,
} as const;
const VERSION = "source-citation-catalog-v1" as const;
// Additional raw-address candidates keep common dish rows, field wrappers and
// individual controls intact across fixed-window boundaries. A candidate does
// not assert that its contents belong together semantically or were rendered.
const SEMANTIC_ELEMENTS = new Set(["h1", "h2", "h3", "title", "label", "p", "li", "tr", "td", "th", "div", "span", "input"]);
const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u;
const encoder = new TextEncoder();
function invalid(): never {throw new DomainError("The source citation catalog input must contain bounded validated source and JSON binding data.", 409);}
function tooLarge(): never {
  throw new DomainError("The complete source citation catalog exceeds the bounded AI request size. No source was truncated or sent.", 413, "ASSESSMENT_CONTEXT_LIMIT");
}
const order = (a: string, b: string) => a < b ? -1 : a > b ? 1 : 0;

/** Snapshot plain JSON before asynchronous hashing. Object property insertion
 * order does not change the binding; accessors, custom serialization and cycles
 * are not interpreted. No binding value is included in a caller-facing error. */
function bindingJson(value: unknown): string {
  const ancestors = new Set<object>(); let visits = 0;
  const encode = (value: unknown, depth: number): string => {
    if (++visits > 100_000 || depth > 64) return invalid();
    if (value === null || typeof value === "boolean" || typeof value === "string") return JSON.stringify(value);
    if (typeof value === "number") return Number.isFinite(value) ? JSON.stringify(value) : invalid();
    if (!value || typeof value !== "object" || ancestors.has(value)) return invalid();
    ancestors.add(value);
    let result: string;
    if (Array.isArray(value)) {
      if (value.length > 100_000) return invalid();
      if (Reflect.ownKeys(value).length !== value.length + 1) return invalid();
      result = `[${Array.from({length: value.length}, (_, i) => {
        const descriptor = Object.getOwnPropertyDescriptor(value, String(i));
        return descriptor && "value" in descriptor ? encode(descriptor.value, depth + 1) : invalid();
      }).join(",")}]`;
    } else {
      if (![Object.prototype, null].includes(Object.getPrototypeOf(value))) return invalid();
      const keys = Reflect.ownKeys(value);
      if (keys.some(key => typeof key !== "string")) return invalid();
      result = `{${(keys as string[]).sort(order).map(key => {
        const descriptor = Object.getOwnPropertyDescriptor(value, key)!;
        return "value" in descriptor ? `${JSON.stringify(key)}:${encode(descriptor.value, depth + 1)}` : invalid();
      }).join(",")}}`;
    }
    ancestors.delete(value);
    return result;
  };
  return encode(value, 0);
}

function sourceSnapshot(files: Record<string, string>): [string, string][] {
  if (!files || typeof files !== "object" || Array.isArray(files) || ![Object.prototype, null].includes(Object.getPrototypeOf(files))) return invalid();
  const keys = Reflect.ownKeys(files);
  if (!keys.length || keys.length > STATIC_RESOURCE_LIMITS.maxFiles) return invalid();
  const seen = new Set<string>(); let total = 0;
  return keys.map(key => {
    assertStaticPath(key);
    const file = key as string, descriptor = Object.getOwnPropertyDescriptor(files, file)!;
    if (!descriptor || !("value" in descriptor) || typeof descriptor.value !== "string" || !["html", "css"].includes(staticFileKind(file) ?? "")) return invalid();
    const source = descriptor.value as string, bytes = encoder.encode(source).byteLength;
    if (!source.trim() || CONTROL.test(source) || [...source].some(character => {const point = character.codePointAt(0)!; return point >= 0xd800 && point <= 0xdfff;})
      || bytes > STATIC_RESOURCE_LIMITS.textFileBytes || seen.has(file.toLowerCase())) return invalid();
    seen.add(file.toLowerCase()); total += bytes;
    if (total > STATIC_RESOURCE_LIMITS.textTotalBytes) return invalid();
    return [file, source] as [string, string];
  }).sort(([a], [b]) => order(a, b));
}

/** This is a raw-source address catalog, not a visibility or semantic verifier.
 * Complete fixed windows preserve all supplied text, including comments, script
 * text, later contradictions and malformed markup. Extra parse5 spans are exact
 * original slices, never HTML serialization or decoded/normalized text. If the
 * complete set exceeds either budget, no partial catalog is returned. */
export async function createAssessmentCitationCatalog(files: Record<string, string>, binding: unknown): Promise<AssessmentCitationCatalog> {
  const snapshot = sourceSnapshot(files), bound = bindingJson(binding);
  const spans: Omit<AssessmentCitationCatalogEntry, "id">[] = [], seen = new Set<string>();
  const add = (file: string, source: string, start: number, end: number) => {
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start < 0 || end <= start || end > source.length
      || end - start > ASSESSMENT_CITATION_CATALOG_LIMITS.excerptUnits) return;
    const key = `${file}\u0000${start}\u0000${end}`;
    if (seen.has(key)) return;
    seen.add(key); spans.push({file, start, end, excerpt: source.slice(start, end)});
    if (spans.length > ASSESSMENT_CITATION_CATALOG_LIMITS.entries) tooLarge();
  };
  for (const [file, source] of snapshot) {
    for (let start = 0; start < source.length;) {
      let end = Math.min(start + ASSESSMENT_CITATION_CATALOG_LIMITS.windowUnits, source.length);
      // A UTF-16 window never separates a valid surrogate pair.
      if (end < source.length && source.charCodeAt(end - 1) >= 0xd800 && source.charCodeAt(end - 1) <= 0xdbff
        && source.charCodeAt(end) >= 0xdc00 && source.charCodeAt(end) <= 0xdfff) end--;
      add(file, source, start, end); start = end;
    }
    if (staticFileKind(file) !== "html") continue;
    const document = parse(source, {sourceCodeLocationInfo: true, scriptingEnabled: true});
    const pending: DefaultTreeAdapterTypes.Node[] = [document];
    while (pending.length) {
      const node = pending.pop()!;
      if ("tagName" in node && node.namespaceURI === "http://www.w3.org/1999/xhtml" && SEMANTIC_ELEMENTS.has(node.tagName)) {
        const at = node.sourceCodeLocation;
        if (at) add(file, source, at.startOffset, at.endOffset);
      }
      if ("childNodes" in node) for (let i = node.childNodes.length - 1; i >= 0; i--) pending.push(node.childNodes[i]);
    }
  }
  spans.sort((a, b) => order(a.file, b.file) || a.start - b.start || a.end - b.end);
  const entries = spans.map((span, index) => ({id: `s${index + 1}`, ...span}));
  const budgetShape = {version: VERSION, catalogId: "0".repeat(64), entries};
  if (encoder.encode(JSON.stringify(budgetShape)).byteLength > ASSESSMENT_CITATION_CATALOG_LIMITS.serializedBytes) tooLarge();
  const payload = `[${JSON.stringify(VERSION)},${bound},${JSON.stringify(snapshot)},${JSON.stringify(entries)}]`;
  const catalogId = [...new Uint8Array(await crypto.subtle.digest("SHA-256", encoder.encode(payload)))].map(byte => byte.toString(16).padStart(2, "0")).join("");
  for (const entry of entries) Object.freeze(entry);
  Object.freeze(entries);
  return Object.freeze({version: VERSION, catalogId, entries});
}

/** A selector is data only. Preserve the server-selected occurrence directly;
 * never use indexOf, repair an unknown selector, or accept a model quotation.
 * The caller checks the top-level catalog binding and expanded report budget. */
export function resolveCatalogCitations(value: unknown, catalog: AssessmentCitationCatalog, maximum: number): ProofAssessmentCitation[] {
  if (!Number.isSafeInteger(maximum) || maximum < 1 || maximum > ASSESSMENT_ITEM_CITATION_LIMIT || !Array.isArray(value) || value.length > maximum)
    throw new AssessmentResponseError("structure");
  const entries = new Map(catalog.entries.map(entry => [entry.id, entry]));
  if (entries.size !== catalog.entries.length) throw new AssessmentResponseError("citation");
  const selected = new Set<string>();
  return value.map(id => {
    if (typeof id !== "string" || selected.has(id)) throw new AssessmentResponseError("citation");
    const entry = entries.get(id);
    if (!entry || !entry.excerpt.trim()) throw new AssessmentResponseError("citation");
    selected.add(id);
    return {file: entry.file, start: entry.start, end: entry.end, excerpt: entry.excerpt};
  });
}

import type {AssessmentCitationEncoding} from "./assessment-completion.ts";
import {ASSESSMENT_ITEM_CITATION_LIMIT} from "./assessment-limits.ts";
import {AssessmentResponseError} from "./assessment-response.ts";

const fail = (reason: "structure" | "citation" = "structure"): never => {throw new AssessmentResponseError(reason);};
function plain(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object" && !Array.isArray(value)
    && [Object.prototype, null].includes(Object.getPrototypeOf(value));
}

/** Decode selectors, never source text. V3 must contain precisely the fixed
 * c1..cN data fields, with a contiguous selected prefix and trailing empty
 * strings. IDs stay verbatim for the existing catalog resolver; unknown IDs
 * cannot be repaired here. Earlier encodings retain their original validators. */
export function assessmentCitationSelection(value: unknown, maximum: number, encoding: AssessmentCitationEncoding): unknown {
  if (encoding !== "catalog_slots") return value;
  if (!Number.isSafeInteger(maximum) || maximum < 1 || maximum > ASSESSMENT_ITEM_CITATION_LIMIT || !plain(value)) return fail();
  const keys = Reflect.ownKeys(value), expected = Array.from({length: maximum}, (_, index) => `c${index + 1}`);
  if (keys.length !== expected.length || keys.some(key => typeof key !== "string" || !expected.includes(key))) return fail();
  const slots = expected.map(key => {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!descriptor || !("value" in descriptor) || typeof descriptor.value !== "string") return fail();
    return descriptor.value as string;
  });
  const selected = slots.filter(slot => slot !== "");
  if (new Set(selected).size !== selected.length) return fail("citation");
  const firstEmpty = slots.indexOf("");
  if (firstEmpty !== -1 && slots.slice(firstEmpty).some(slot => slot !== "")) return fail();
  return selected;
}

/** Normalize only the selectors in a separate validation view. Raw provider
 * items are untouched. Missing fields, statuses, IDs, extra fields and list
 * bounds remain the existing item/coverage validators' responsibility. */
export function assessmentItemsForValidation(value: unknown, encoding: AssessmentCitationEncoding): unknown {
  if (encoding !== "catalog_slots" || !Array.isArray(value)) return value;
  return value.map(item => {
    if (!plain(item)) return item;
    const keys = Reflect.ownKeys(item);
    if (keys.some(key => typeof key !== "string" || !("value" in Object.getOwnPropertyDescriptor(item, key)!)) || !Object.hasOwn(item, "citations")) return item;
    return {...item, citations: assessmentCitationSelection(item.citations, ASSESSMENT_ITEM_CITATION_LIMIT, encoding)};
  });
}

import {AssessmentResponseError} from "./assessment-response.ts";
import {ASSESSMENT_ITEM_CITATION_LIMIT, ASSESSMENT_RISK_CITATION_LIMIT} from "./assessment-limits.ts";

export const SOURCE_ASSESSMENT_TOOL_NAME = "submit_source_assessment";
export const SOURCE_ASSESSMENT_CATALOG_TOOL_NAME = "submit_source_assessment_v2";
export const SOURCE_ASSESSMENT_SLOTS_TOOL_NAME = "submit_source_assessment_v3";
export type AssessmentCitationEncoding = "catalog_slots" | "catalog_ids" | "legacy_quotes";
export type AssessmentCompletionTransport = "strict_tool" | "legacy_json";
const fail = (reason: "structure" | "output_limit" | "incomplete" = "structure"): never => {throw new AssessmentResponseError(reason);};
function record(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value) || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) return fail();
  return value as Record<string, unknown>;
}
function content(value: unknown): string {
  if (typeof value !== "string" || !value.trim()) return fail();
  return value;
}

/** Decode one report envelope, never execute a tool or interpret its contents as
 * instructions. The caller must still perform the complete JSON, bounds,
 * criterion coverage, risk-field and exact source-citation validation. */
export function assessmentCompletionText(providerBody: unknown, encoding: AssessmentCitationEncoding = "legacy_quotes"): {text: string; transport: AssessmentCompletionTransport} {
  const body = record(providerBody);
  if (!Array.isArray(body.choices) || body.choices.length !== 1) return fail();
  const choice = record(body.choices[0]);
  if (choice.finish_reason === "length") return fail("output_limit");
  if (choice.finish_reason !== "tool_calls" && choice.finish_reason !== "stop") return fail("incomplete");
  const message = record(choice.message);
  if (choice.finish_reason === "stop") {
    if (encoding !== "legacy_quotes") return fail();
    // Null/empty legacy metadata is harmless. A real or malformed call alongside
    // a stop/content answer is ambiguous and cannot be silently ignored.
    if (message.tool_calls !== undefined && message.tool_calls !== null
      && (!Array.isArray(message.tool_calls) || message.tool_calls.length !== 0)) return fail();
    return {text: content(message.content), transport: "legacy_json"};
  }
  if (!Array.isArray(message.tool_calls) || message.tool_calls.length !== 1) return fail();
  const call = record(message.tool_calls[0]);
  if (call.type !== "function") return fail();
  const fn = record(call.function);
  const expectedTool = encoding === "catalog_slots" ? SOURCE_ASSESSMENT_SLOTS_TOOL_NAME
    : encoding === "catalog_ids" ? SOURCE_ASSESSMENT_CATALOG_TOOL_NAME : SOURCE_ASSESSMENT_TOOL_NAME;
  if (fn.name !== expectedTool) return fail();
  return {text: content(fn.arguments), transport: "strict_tool"};
}

/** One provable syntax-only compatibility: strict arguments may contain one
 * orphan closing brace after a complete JSON object. A successful second parse
 * of precisely that prefix proves no field/value was inserted or edited. Never
 * repairs legacy text, strings/arrays, partial JSON, multiple objects, arbitrary
 * suffixes or more than one brace. Evaluation retains the original envelope;
 * callers expose normalization as a fixed system note. */
export function assessmentReportJson(completion:{text:string;transport:AssessmentCompletionTransport}):{value:unknown;canonicalText:string;repairedTrailingBrace:boolean}{
  if(completion.text.length>30_000)return fail();
  try{return{value:JSON.parse(completion.text),canonicalText:completion.text,repairedTrailingBrace:false};}
  catch{
    const trimmed=completion.text.trim();
    if(completion.transport!=="strict_tool"||!trimmed.endsWith("}"))return fail();
    const candidate=trimmed.slice(0,-1);
    let value:unknown;
    try{value=JSON.parse(candidate);}catch{return fail();}
    if(!value||typeof value!=="object"||Array.isArray(value))return fail();
    return{value,canonicalText:candidate,repairedTrailingBrace:true};
  }
}

const textSchema = (description: string) => ({type: "string", pattern: "\\S", description});
function objectSchema<T extends Record<string, unknown>>(properties: T) {
  return {type: "object", properties, required: Object.keys(properties), additionalProperties: false};
}

/** Built from already validated locked IDs and supplied source filenames. Strict
 * Beta schema omits unsupported array/string size keywords; local validators
 * retain all cardinality, length, citation and semantic-scope controls. */
export function assessmentToolDefinition(criterionIds: readonly string[], sourceFiles: readonly string[]) {
  const citation = objectSchema({file: {type: "string", enum: [...sourceFiles]}, excerpt: textSchema("Exact contiguous supplied source substring; at most 500 characters.")});
  const citations = {type: "array", items: citation, description: `At most ${ASSESSMENT_ITEM_CITATION_LIMIT} exact supplied-source quotations. May be empty only for an insufficient-evidence item.`};
  const item = objectSchema({criterionId: {type: "string", enum: [...criterionIds]}, status: {type: "string", enum: ["supported", "changes_suggested", "insufficient_evidence"]},
    explanation: textSchema("Concise source-based explanation, at most 600 characters."), citations});
  const risk = objectSchema({title: textSchema("Evidence-layer potential issue title, at most 120 characters."),
    explanation: textSchema("Source-grounded explanation, at most 600 characters."), suggestion: textSchema("A concrete next check, at most 400 characters."),
    citations: {type: "array", items: citation, description: `One to ${ASSESSMENT_RISK_CITATION_LIMIT} exact supplied-source quotations.`}});
  return {type: "function", function: {name: SOURCE_ASSESSMENT_TOOL_NAME, strict: true,
    description: "Return a source-assessment report as data only. This output container is never executed and cannot accept work, move money or perform any external action.",
    parameters: objectSchema({items: {type: "array", items: item, description: "Exactly one item for every locked criterion ID, in its supplied order; never merge, duplicate or omit an ID."},
      risks: {type: "array", items: risk, description: "At most five concrete source-grounded potential issues; each requires all four fields."},
      limitations: {type: "array", items: textSchema("One remaining uncertainty, at most 300 characters."), description: "At most eight remaining uncertainties."}})}};
}

/** Explicit V2 replay protocol: the provider selects immutable server-owned spans. Strict
 * enums constrain syntax; local resolution still checks identity, cardinality,
 * duplicates and expanded-report bounds. IDs do not establish semantic support. */
export function assessmentCatalogToolDefinition(criterionIds: readonly string[], catalog: {catalogId:string;entries:readonly {id:string}[]}) {
  const old = assessmentToolDefinition(criterionIds, []);
  const citation = {type: "string", enum: catalog.entries.map(entry => entry.id)};
  const parameters = old.function.parameters;
  parameters.properties.items.items.properties.citations.items = citation as never;
  parameters.properties.items.items.properties.citations.description = `At most ${ASSESSMENT_ITEM_CITATION_LIMIT} distinct source-catalog IDs, enough context to witness every asserted relationship.`;
  parameters.properties.risks.items.properties.citations.items = citation as never;
  parameters.properties.risks.items.properties.citations.description = `One to ${ASSESSMENT_RISK_CITATION_LIMIT} distinct source-catalog IDs.`;
  return {type: "function", function: {...old.function, name: SOURCE_ASSESSMENT_CATALOG_TOOL_NAME,
    parameters: objectSchema({catalogId:{type:"string",enum:[catalog.catalogId]}, ...parameters.properties})}};
}

/** V3 expresses the citation count in supported strict-schema object shape,
 * rather than relying on an unsupported maxItems keyword or prompt wording.
 * Empty strings mark only trailing unused slots. Local selection still rejects
 * gaps and duplicates; catalog identity and exact source resolution remain
 * separate checks, and no slot establishes semantic support. */
export function assessmentSlotsToolDefinition(criterionIds: readonly string[], catalog: {catalogId:string;entries:readonly {id:string}[]}) {
  const old = assessmentCatalogToolDefinition(criterionIds, catalog), parameters = old.function.parameters;
  const ids = catalog.entries.map(entry => entry.id);
  const slots = (maximum: number, requiredFirst: boolean) => objectSchema(Object.fromEntries(Array.from({length: maximum}, (_, index) => [
    `c${index + 1}`, {type: "string", enum: index === 0 && requiredFirst ? [...ids] : ["", ...ids],
      description: index === 0 && requiredFirst ? "First exact source-catalog ID; a risk must cite source evidence."
        : "Exact source-catalog ID, or empty only when this and all later slots are unused."},
  ])));
  const item = objectSchema({...parameters.properties.items.items.properties,
    citations: slots(ASSESSMENT_ITEM_CITATION_LIMIT, false)});
  const risk = objectSchema({...parameters.properties.risks.items.properties,
    citations: slots(ASSESSMENT_RISK_CITATION_LIMIT, true)});
  return {type: "function", function: {...old.function, name: SOURCE_ASSESSMENT_SLOTS_TOOL_NAME,
    parameters: objectSchema({...parameters.properties,
      items: {...parameters.properties.items, items: item}, risks: {...parameters.properties.risks, items: risk}})}};
}

import type {Language, ProofEvidenceNeed} from "./contracts.ts";
import {staticFileKind} from "./static-resources.ts";

export const ASSESSMENT_EVIDENCE_NEED_REASONS = ["browser_observation", "direct_observation", "financial_execution", "record_readback", "requirement_clarification", "manual_interpretation", "page_scope", "page_citations", "field_relationship", "source_ambiguity", "no_citations", "model_unresolved"] as const satisfies readonly ProofEvidenceNeed["reason"][];
const PATH = /^(?:[A-Za-z0-9][A-Za-z0-9._-]{0,63}\/){0,4}[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/u;

/** Presentation accepts old/untrusted saved shapes without guessing a cause.
 * Export validation separately rejects invalid metadata and checks membership
 * in that delivery's actual files; this does not repair or persist a payload. */
export function isAssessmentEvidenceNeed(value: unknown): value is ProofEvidenceNeed {
  if (!value || typeof value !== "object" || Array.isArray(value) || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) return false;
  const keys = Reflect.ownKeys(value);
  if (keys.length !== 3 || keys.some(key => typeof key !== "string" || !["schema", "reason", "targetFiles"].includes(key) || !("value" in Object.getOwnPropertyDescriptor(value, key)!))) return false;
  const row = value as Record<string, unknown>;
  if (row.schema !== "source-evidence-need-v1" || typeof row.reason !== "string"
    || !(ASSESSMENT_EVIDENCE_NEED_REASONS as readonly string[]).includes(row.reason) || !Array.isArray(row.targetFiles) || row.targetFiles.length > 40) return false;
  const targets = row.targetFiles;
  if (Reflect.ownKeys(targets).length !== targets.length + 1) return false;
  const files: string[] = [];
  for (let index = 0; index < targets.length; index++) {
    const descriptor = Object.getOwnPropertyDescriptor(targets, String(index));
    if (!descriptor || !("value" in descriptor) || typeof descriptor.value !== "string") return false;
    const file = descriptor.value as string;
    if (file.length > 300 || !PATH.test(file) || !["html", "css"].includes(staticFileKind(file) ?? "")) return false;
    files.push(file);
  }
  return new Set(files).size === files.length;
}

/** Called only from an actual server guard branch. Keep exact provided keys,
 * never normalize an alias or infer a file from model wording/page roles. */
export function makeAssessmentEvidenceNeed(reason: ProofEvidenceNeed["reason"], candidates: readonly string[], sent: Record<string, string>): ProofEvidenceNeed {
  return {schema: "source-evidence-need-v1", reason, targetFiles: [...new Set(candidates)].filter(file => Object.hasOwn(sent, file)
    && file.length <= 300 && PATH.test(file) && ["html", "css"].includes(staticFileKind(file) ?? ""))};
}

