  // must itself identify a policy/copy requirement rather than a capability.
  if (titleWithoutBooking !== title && !POLICY_COPY_TITLE.test(title)) return false;
  return (sourceWithoutBooking !== source || titleWithoutBooking !== title || POLICY_COPY_TITLE.test(title))
    && !OBSERVATION_REQUIRED.test(`${titleWithoutBooking}\n${sourceWithoutBooking}`);
}

// A narrow wording-only allowance for cancellation eligibility. Here "receive"
// describes what the page must say, not an observed refund. The complete body
// must match: adding payment execution, another runtime clause or unfamiliar
// wording cannot inherit this exemption. The model still has to ground its
// verdict in exact citations; this classifier does not establish the policy.
const REFUND_POLICY_COPY = /^cancellations?\s+(?:made\s+)?at\s+least\s+[1-9]\d{0,3}\s+(?:hours?|days?)\s+before\s+departure\s+receive\s+a\s+full\s+refund$/iu;
// Explicit money-moving actions take precedence even if another clause says
// "copy". This is deliberately an action vocabulary, not a blanket ban on the
// words refund/退款 in ordinary policy text. It is a conservative boundary,
// not a complete natural-language parser or a financial execution check.
const FINANCIAL_ACTION = /\b(?:(?:issu(?:e[sd]?|ing)|process(?:es|ed|ing)?|execut(?:e[sd]?|ing)|initiat(?:e[sd]?|ing)|trigger(?:s|ed|ing)?|settl(?:e[sd]?|ing)|disburs(?:e[sd]?|ing))\s+(?:(?:a|an|the|full|partial|automatic|real|actual|successful|customer|payment)\s+){0,4}refunds?|refund(?:s|ed|ing)?\s+(?:the|an?|original|customer'?s?)\s+(?:card|payment|money|funds|account)|(?:actually|automatically|successfully)\s+(?:(?:issue|process|execute|initiate|trigger|settle|disburse|complete|perform|make)\s+)?(?:(?:a|an|the|full|partial|real|actual)\s+){0,4}(?:refunds?|charges?|captures?|payments?)|refunds?\s+(?:are\s+|must\s+be\s+)?(?:issued|processed|executed|initiated|triggered|settled|disbursed)\s+(?:actually|automatically|successfully))\b|(?:实际|自动|真实)(?:地)?(?:进行|发起|执行|处理|完成)?(?:退款|扣款|支付)|(?:发起|执行|处理|完成)(?:实际|自动|真实)?(?:退款|扣款|支付)/iu;
// Further explicit operation families reproduced with controlled overclaims.
// These bounded verb/object relationships are not a general semantic parser or
// a ban on a product name, payment column heading or exact quoted wording.
const CARD_DEBIT_ACTION = /\b(?:(?:deduct|debit)(?:s|ed|ing)?|withdraw(?:s|ing)?|withdrew|withdrawn)\s+(?:(?:the|a|an|actual|real)\s+){0,3}(?:fees?|amounts?|money|funds?|charges?)\s+from\s+(?:(?:the|a|an|original|customer['’]s)\s+){0,3}(?:card|account|balance)\b|\bdebit(?:s|ed|ing)?\s+(?:(?:the|a|an|original|customer['’]s)\s+){0,3}card\s+for\s+(?:(?:the|a|an)\s+)?fee\b/iu;
const EMAIL_DELIVERY_ACTION = /\bguarantee(?:s|d|ing)?\s+(?:(?:real|actual|successful)\s+)?(?:email\s+delivery|delivery\s+of\s+(?:(?:real|actual|successful|notification|confirmation)\s+){0,3}emails?)\b/iu;
function isExplicitRefundPolicyCopy(criterion: ProofCriterion): boolean {
  const directive = POLICY_COPY_DIRECTIVE.exec(criterion.source.trim());
  if (!directive || OBSERVATION_REQUIRED.test(criterion.title)) return false;
  const body = criterion.source.trim().slice(directive[0].length).trim().replace(/^[：:\s"'“‘]+/u, "").replace(/[。.!?！？"'”’\s]+$/u, "");
  return REFUND_POLICY_COPY.test(body);
}

// These unambiguous record capabilities need state/readback evidence even when
// another part of the requirement mentions receipt "copy" or page content.
// This remains conservative bounded language, not a complete semantic parser.
const RECORD_ACTION = /\b(?:record(?:s|ed|ing)?|archiv(?:e[sd]?|ing)|log(?:s|ged|ging)?|stor(?:e[sd]?|ing)|retain(?:s|ed|ing)?|writ(?:e[sd]?|ing)|queue(?:s|d|ing)?)\b[^.。；;\n]{0,180}\b(?:enquir(?:y|ies)|inquir(?:y|ies)|requests?|receipts?|records?|submissions?|transactions?|customer\s+data|audit\s+trail)\b|\b(?:enquir(?:y|ies)|inquir(?:y|ies)|requests?|receipts?|records?|submissions?|transactions?|audit\s+trail)\b[^.。；;\n]{0,120}\b(?:durab(?:le|ly|ility)|archived|logged|stored|retained|queryable|retrievable|persistently|permanently)\b|(?:询价|咨询|请求|回执|记录|交易|提交内容)[^。；;\n]{0,80}(?:落库|持久|留存|入库|可查询|可检索|重启后保留)|(?:落库|持久保存|持久记录|持久存储|留存|入库|归档|记录|存储)[^。；;\n]{0,80}(?:询价|咨询请求|回执|交易|提交内容)|\b(?:receipts?|records?|audit\s+trail)\b[^.。；;\n]{0,120}\b(?:after\s+(?:a\s+|the\s+)?(?:server\s+)?restart|survive\s+(?:a\s+)?restart)\b/iu;
const CUSTOMER_DATA_REBOOT = /\bcustomer\s+data\s+(?:(?:must|should|shall|will)\s+)?surviv(?:e[sd]?|ing)\s+(?:(?:a|the)\s+)?(?:server\s+)?(?:reboot|restart)\b/iu;

type StaticRelationDescriptor = {identity: string; files: string[]} & (
  {kind: "label_for_id"; labels: string[]}
  | {kind: "input_type"; label: string; inputType: string; ratherThan?: string}
  | {kind: "radio_group"; labels: string[]; values: string[]; name: string}
);
const RELATION_LABEL = "[A-Z][A-Za-z0-9_-]{0,39}(?: [a-z][A-Za-z0-9_-]{0,39}){0,3}";
const RELATION_OPERATION = /\b(?:and|or|then|also|after|before|when|while|must|shall|should|will|can|could|actual|actually|automatically|click(?:s|ed|ing)?|save|store|reload|submit|send|visible|visually|secure|security|persist|record)\b/iu;
const INPUT_TYPES = new Set(["button", "checkbox", "color", "date", "datetime-local", "email", "file", "hidden", "image", "month", "number", "password", "radio", "range", "reset", "search", "submit", "tel", "text", "time", "url", "week"]);

function relationFile(value: string): string | undefined {
  try {const file = assertStaticPath(value); return file.endsWith(".html") ? file : undefined;} catch {return;}
}
function relationLabel(value: string): boolean {
  return new RegExp(`^${RELATION_LABEL}$`, "u").test(value) && value.length <= 80 && !RELATION_OPERATION.test(value);
}
function relationLabels(value: string): string[] | undefined {
  // Explicit finite lists: capital-start labels, optional lower-case words in
  // each label, and one final "and". Do not split arbitrary natural language.
  const parts = value.split(/\s+and\s+/u); if (parts.length !== 2 || !relationLabel(parts[1])) return;
  const labels: string[] = []; let cursor = 0;
  for (const match of parts[0].matchAll(new RegExp(RELATION_LABEL, "gu"))) {
    const gap = parts[0].slice(cursor, match.index);
    if (labels.length ? !/^(?: +|, *)$/u.test(gap) : gap !== "") return;
    if (!relationLabel(match[0])) return;
    labels.push(match[0]); cursor = match.index + match[0].length;
  }
  if (cursor !== parts[0].length) return;
  labels.push(parts[1]);
  return labels.length >= 2 && labels.length <= 6 && new Set(labels).size === labels.length ? labels : undefined;
}
function relationInputType(value: string): string | undefined {
  const match = /^(?:"([a-z-]+)"|'([a-z-]+)'|([a-z-]+))$/u.exec(value), type = match?.slice(1).find(part => part !== undefined);
  return type && INPUT_TYPES.has(type) ? type : undefined;
}
/** Admission descriptor only. Complete atomic syntax binds the named files,
 * labels and attributes to static source data; it neither inspects delivered
 * nodes nor establishes a for/id, tuple, input-type or runtime verdict. */
function staticRelationDirective(source: string): StaticRelationDescriptor | undefined {
  const text = source.trim(); if (text.length > 800 || /[\r\n]/u.test(text)) return;
  const body = text.replace(/\.$/u, ""), identity = text.replace(/[\t ]+/gu, " ");
  const labelPair = /^The static HTML labels (.+) on (\S+) must each target its matching input through a for and id pair$/u.exec(body);
  if (labelPair) {
    const labels = relationLabels(labelPair[1]), file = relationFile(labelPair[2]);
    return labels && file ? {identity, kind: "label_for_id", files: [file], labels} : undefined;
  }
  const input = /^The static (.+) control markup in (.+) must use input type (\S+)(?: rather than (\S+))?$/u.exec(body);
  if (input) {
    if (!relationLabel(input[1])) return;
    const pair = /^both (\S+) and (\S+)$/u.exec(input[2]), targets = pair ? pair.slice(1) : [input[2]];
    const files = targets.map(relationFile), inputType = relationInputType(input[3]), ratherThan = input[4] === undefined ? undefined : relationInputType(input[4]);
    if (files.some(file => file === undefined) || new Set(files).size !== files.length || !inputType || input[4] !== undefined && !ratherThan) return;
    return {identity, kind: "input_type", files: files as string[], label: input[1], inputType, ...(ratherThan ? {ratherThan} : {})};
  }
  const radio = /^The (\S+) source content must pair (.+) radio labels with values (.+) under the same ([A-Za-z][A-Za-z0-9_-]{0,39}) name$/u.exec(body);
  if (!radio) return;
  const file = relationFile(radio[1]), labels = relationLabels(radio[2]), valueParts = radio[3].split(/\s+and\s+/u);
  if (!file || !labels || valueParts.length !== 2) return;
  const values = [...valueParts[0].split(/(?:,\s*| +)/u), valueParts[1]];
  if (values.length !== labels.length || new Set(values).size !== values.length || values.some(value => !/^(?:0|[1-9]\d{0,2})$/u.test(value))) return;
  return {identity, kind: "radio_group", files: [file], labels, values, name: radio[4]};
}
function isStaticRelationCandidate(source: string): boolean {
  const text = source.trim();
  return /^The static HTML labels /u.test(text) || /^The static [^\r\n]{1,100} control markup in /u.test(text)
    || /^The \S+ source content must pair /u.test(text);
}

/** Admission controls do not establish whether a model's cited inference is true. */
export function assessmentEvidenceScope(criterion: ProofCriterion): AssessmentEvidenceScope {
  const literal = exactCopyLiteral(criterion.source), sourceDirective = sourceLiteralDirective(criterion.source), relationDirective = staticRelationDirective(criterion.source);
  const markupDirective = staticMarkupDirective(criterion.source) ?? relationDirective?.identity;
  // A title that repeats the same whole exact-copy directive adds no separate
  // obligation. Other titles retain their own runtime/financial/record veto.
  // In particular, do not infer a text-only scope from a truncated title.
  const repeatedLiteralTitle = literal !== undefined && exactCopyLiteral(criterion.title) === literal;
  const repeatedSourceTitle = sourceDirective !== undefined && sourceLiteralDirective(criterion.title) === sourceDirective;
  const repeatedMarkupTitle = markupDirective !== undefined && (staticMarkupDirective(criterion.title) ?? staticRelationDirective(criterion.title)?.identity) === markupDirective;
  const title = repeatedLiteralTitle || repeatedSourceTitle || repeatedMarkupTitle ? "" : criterion.title;
  const sourceOnlyDirective = literal !== undefined || sourceDirective !== undefined || markupDirective !== undefined;
  // Complete quoted literals and atomic markup-property statements bind their
  // contents to source data. The unquoted label/notice grammar still receives
  // every financial and durable-record veto before its text-only allowance.
  const combined = literal !== undefined || markupDirective !== undefined ? title : `${title}\n${criterion.source}`;
  if (criterion.id === "mobile") return { category: "requires_observation", reason: "mobile" };
  if (FINANCIAL_ACTION.test(combined) || CARD_DEBIT_ACTION.test(combined)) return { category: "requires_observation", reason: "financial_action" };
  if (RECORD_ACTION.test(combined) || CUSTOMER_DATA_REBOOT.test(combined)) return { category: "requires_observation", reason: "durable_record" };
  if (EMAIL_DELIVERY_ACTION.test(combined)) return {category: "requires_observation", reason: "runtime_or_subjective"};
  if (!sourceOnlyDirective && (isSourceLiteralDirectiveCandidate(criterion.source) || isStaticMarkupDirectiveCandidate(criterion.source) || isStaticRelationCandidate(criterion.source))) return {category: "requires_observation", reason: "unclassified_requirement"};
  if (sourceOnlyDirective) return OBSERVATION_REQUIRED.test(withoutWorkingTimeUnits(title))
    || relationDirective !== undefined && /\b(?:visib(?:le|ility)|visually|masked|masking|security|secure(?:ly)?|protection|protect(?:s|ed|ing)?)\b/iu.test(title)
    ? {category: "requires_observation", reason: "runtime_or_subjective"}
    : {category: "source_text", reason: "literal_content"};
  const policyCopy = isExplicitBookingPolicyCopy(criterion) || isExplicitRefundPolicyCopy(criterion);
  if (!policyCopy && OBSERVATION_REQUIRED.test(withoutWorkingTimeUnits(combined))) return { category: "requires_observation", reason: "runtime_or_subjective" };
  if (/^(?:manual|coverage)-/u.test(criterion.id) && !policyCopy && !SOURCE_CONTENT.test(criterion.source)
    && !PUBLISHED_POLICY_TEXT.test(criterion.source) && !ZH_CANCELLATION_WORDING.test(criterion.source.trim()) && !DISPLAYED_BUSINESS_HOURS.test(criterion.source)) {
    return { category: "requires_observation", reason: "unclassified_requirement" };
  }
  return { category: "source_text", reason: policyCopy ? "explicit_policy_copy" : /^(?:manual|coverage)-/u.test(criterion.id) ? "literal_content" : "other_source_rule" };
}

/** Fixed explanations describe the evidence still needed, never provider claims. */
export function assessmentObservationExplanation(scope: AssessmentEvidenceScope, language: Language): string {
  const zh = language === "zh";
  if (scope.reason === "durable_record") return zh
    ? "本项要求实际记录、持久留存或可查询的回执；源码中的文案不能证明记录已写入或可回读。请提供运行结果与独立记录回读证据，并核对完整锁定要求。"
    : "This requirement includes actual records, durable retention or queryable receipts. Source copy cannot establish that records were written or can be read back. Provide execution and independent record-readback evidence, and check the complete locked requirement.";
  if (scope.reason === "financial_action") return zh
    ? "本项包含实际退款、扣款或支付操作；源码政策文案不能证明资金操作已完成。请补充对应执行结果与交易记录，并核对完整锁定要求。"
    : "This requirement includes an actual refund, charge or payment operation. Source policy copy cannot establish that money moved. Supply the execution result and transaction record, and check the complete locked requirement.";
  if (scope.reason === "mobile") return zh
    ? "本项需要实际手机视口的浏览器观察与买家确认；源码文本不能证明移动端体验。"
    : "This requirement needs browser observations at a mobile viewport and buyer confirmation. Source text cannot establish the mobile experience.";
  return zh
    ? "本项不属于明确可用源码核对的文本内容要求，或含运行、交互、手机体验及主观判断；需要其他证据或买家实际确认。"
    : "This is not an explicit source-checkable text-content requirement, or it includes runtime, interaction, mobile or subjective claims. Other evidence or direct buyer confirmation is needed.";
}

import {parse, type DefaultTreeAdapterTypes} from "parse5";
import type {Language, ProofAssessmentCitation, ProofCriterion} from "./contracts.ts";
import {parseSourceLiteralDirective} from "./source-literal-directive.ts";
import {normalizeExactCopyWhitespace as normalized} from "./exact-copy-directive.ts";
import {ASSESSMENT_ITEM_CITATION_LIMIT} from "./assessment-limits.ts";

type Node = DefaultTreeAdapterTypes.Node;
type Element = DefaultTreeAdapterTypes.Element;
type Part = {start: number; end: number; value: string};
type Label = {text: string; form?: string; parts: Part[]};
export type LabelCitationCoverage = {kind: "not_applicable" | "covered"}
  | {kind: "incomplete"; context: "page" | "form"; missingLabels: string[]}
  | {kind: "unknown"; context: "page" | "form"};
const element = (node: Node): node is Element => "tagName" in node;
const INERT = new Set(["head", "script", "style", "template", "noscript", "textarea", "title", "iframe", "xmp", "noembed", "noframes", "plaintext"]);

function labelsIn(source: string): Label[] | undefined {
  let issue = false, visits = 0;
  const document = parse(source, {sourceCodeLocationInfo: true, scriptingEnabled: true,
    onParseError: error => {if (error.code !== "missing-doctype") issue = true;}});
  const labels: Label[] = [], stack: {node: Node; form?: string; depth: number}[] = [{node: document, depth: 0}];
  while (stack.length) {
    const {node, form, depth} = stack.pop()!;
    if (++visits > 50_000 || depth > 512) return;
    let group = form;
    if (element(node)) {
      if (node.namespaceURI !== "http://www.w3.org/1999/xhtml" || INERT.has(node.tagName)) continue;
      if (node.tagName === "form") group = String(node.sourceCodeLocation?.startOffset ?? "unlocated");
      if (node.tagName === "label") {
        const parts: Part[] = [], pending: {node: Node; depth: number}[] = [{node, depth: 0}];
        while (pending.length) {
          const next = pending.pop()!;
          if (++visits > 50_000 || next.depth > 512) return;
          if (next.node.nodeName === "#text") {
            const text = next.node as DefaultTreeAdapterTypes.TextNode, at = text.sourceCodeLocation;
            if (at) parts.push({start: at.startOffset, end: at.endOffset, value: text.value});
            else if (normalized(text.value)) return;
          } else if (element(next.node) && (next.node.namespaceURI !== "http://www.w3.org/1999/xhtml" || INERT.has(next.node.tagName))) continue;
          if ("childNodes" in next.node) for (let i = next.node.childNodes.length - 1; i >= 0; i--) pending.push({node: next.node.childNodes[i], depth: next.depth + 1});
        }
        labels.push({text: normalized(parts.map(p => p.value).join("")), ...(group ? {form: group} : {}), parts: parts.filter(p => normalized(p.value))});
      }
    }
    if ("childNodes" in node) for (let i = node.childNodes.length - 1; i >= 0; i--) stack.push({node: node.childNodes[i], form: group, depth: depth + 1});
  }
  return issue ? undefined : labels;
}

/** Only witnesses the recognised literal HTML-label family. It does not infer
 * semantic page identity, accessibility associations, visibility or operation.
 * Exact saved source spans prevent comments/attributes or other files from
 * masquerading as quoted label text. No citation or model field is rewritten. */
export function createAssessmentLabelCitationCheck(files: Record<string, string>) {
  const snapshot = {...files}, parsed = new Map<string, Label[] | undefined>();
  return (criterion: ProofCriterion, citations: readonly ProofAssessmentCitation[]): LabelCitationCoverage => {
    const descriptor = parseSourceLiteralDirective(criterion.source);
    if (!descriptor || descriptor.kind !== "html_labels") return {kind: "not_applicable"};
    const labels = descriptor.labels.map(normalized), context = descriptor.context;
    if (new Set(labels).size !== labels.length || citations.length > ASSESSMENT_ITEM_CITATION_LIMIT) return {kind: "unknown", context};
    if (Object.keys(snapshot).length > 40 || Object.values(snapshot).reduce((sum, value) => sum + value.length, 0) > 262_144) return {kind: "unknown", context};
    if (citations.some(c => !Object.hasOwn(snapshot, c.file) || !Number.isSafeInteger(c.start) || !Number.isSafeInteger(c.end) || c.start < 0 || c.end <= c.start || c.end > snapshot[c.file].length || snapshot[c.file].slice(c.start, c.end) !== c.excerpt)) return {kind: "unknown", context};
    const groups = new Map<string, Set<string>>();
    for (const file of [...new Set(citations.map(c => c.file))].sort()) {
      if (!file.endsWith(".html")) continue;
      if (!parsed.has(file)) parsed.set(file, labelsIn(snapshot[file]));
      for (const label of parsed.get(file) ?? []) {
        if (!labels.includes(label.text) || !label.parts.length || context === "form" && !label.form) continue;
        const key = context === "form" ? `${file}\u0000${label.form}` : file;
        if (!groups.has(key)) groups.set(key, new Set());
        const witnessed = label.parts.every(part => {
          const raw = snapshot[file].slice(part.start, part.end);
          const leading = /^[\t\n\f\r \u00a0]*/u.exec(raw)![0].length, trailing = /[\t\n\f\r \u00a0]*$/u.exec(raw)![0].length;
          // Require the whole non-whitespace source span, including every byte
          // of an entity. A cut-off '&' cannot witness an encoded '&amp;'.
          const start = part.start + leading, end = part.end - trailing;
          return citations.some(c => c.file === file && c.start <= start && c.end >= end);
        });
        if (witnessed) groups.get(key)!.add(label.text);
      }
    }
    const complete = [...groups.values()].filter(group => labels.every(label => group.has(label)));
    if (complete.length === 1) return {kind: "covered"};
    if (complete.length > 1) return {kind: "unknown", context};
    const best = [...groups.values()].sort((a, b) => b.size - a.size)[0] ?? new Set<string>();
    return {kind: "incomplete", context, missingLabels: labels.filter(label => !best.has(label))};
  };
}

export function labelCitationCoverageExplanation(result: Extract<LabelCitationCoverage, {context: string}>, language: Language): string {
  const context = result.context === "form" ? language === "zh" ? "同一 HTML 表单" : "one HTML form" : language === "zh" ? "同一 HTML 页面" : "one HTML page";
  if (result.kind === "unknown") return language === "zh"
    ? `源码引文无法唯一对应${context}的标签清单，需补充明确引文。这是引用覆盖不确定，不代表交付缺少字段；原始要求未改变。`
    : `The citations cannot uniquely witness the label list in ${context}. Add clear source evidence; this is uncertain citation coverage, not proof of missing delivery fields.`;
  const shown = result.missingLabels.slice(0, 3).join("; "), remaining = result.missingLabels.length - 3;
  return language === "zh"
    ? `源码引文尚未在${context}覆盖标签：${shown}${remaining > 0 ? `（另 ${remaining} 项）` : ""}。请补充引文；这是引用缺口，不代表交付缺少字段。`
    : `Source citations do not cover these labels in ${context}: ${shown}${remaining > 0 ? ` (+${remaining} more)` : ""}. Add citations; this is an evidence gap, not proof of missing delivery fields.`;
}

/** Item lists can need distinct witnesses; risk evidence retains its old bound.
 * These limits are shared by live decoding, saved/offline reports and scoring. */
export const ASSESSMENT_ITEM_CITATION_LIMIT = 6;
export const ASSESSMENT_RISK_CITATION_LIMIT = 3;

import type {Language, ProofCriterion} from "./contracts.ts";
import {assessmentEvidenceScope} from "./assessment-evidence-scope.ts";
import {exactCopyLiteral} from "./exact-copy-directive.ts";
import {sourceLiteralDirective} from "./source-literal-directive.ts";
import {staticMarkupDirective} from "./static-markup-directive.ts";

export type AssessmentObligationKind = "submission" | "email_delivery" | "durable_write" | "readback" | "restart_readback" | "source_content" | "unclassified";
export type AssessmentObligationState = "execution_not_verified" | "source_review_required" | "needs_clarification";
export type AssessmentObligations = {
  schema: "source-obligations-v1";
  coverage: "bounded_detection";
  sourceLength: number;
  clauses: {start: number; end: number; excerpt: string}[];
  items: {id: string; kind: AssessmentObligationKind; clauseIndex: number; state: AssessmentObligationState}[];
};
const LIMIT = 12;
const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u;
const SUBMISSION = /\bsubmi(?:t|ts|tted|tting|ssion|ssions)\b|提交/u;
const EMAIL = /\b(?:send(?:s|ing)?|sent|deliver(?:s|ed|ing)?|receiv(?:e[sd]?|ing)|guarantee(?:s|d|ing)?)\b[^。；;\n]{0,100}\b(?:e-?mails?|mail\s+(?:messages?|confirmations?))\b|\b(?:e-?mails?)\b[^。；;\n]{0,80}\b(?:deliver(?:ed|y)|sent|received|receipts?)\b|\be-?mail(?:s|ed|ing)?\s+(?:the|our|each|every|an?)\s+(?:owner|customer|buyer|seller|user|recipient)s?\b|(?:发(?:送|出)?|收(?:到|取)?|送达|投递|寄送)[^。；;\n]{0,60}(?:邮件|电子信件)|(?:邮件|电子信件)[^。；;\n]{0,60}(?:送达|发送|投递|收到)/iu;
const WRITE = /\b(?:sav(?:e[sd]?|ing)|stor(?:e[sd]?|ing)|record(?:s|ed|ing)?|writ(?:e[sd]?|ten|ing)|preserv(?:e[sd]?|ing)|retain(?:s|ed|ing)?|archiv(?:e[sd]?|ing))\b[^。；;\n]{0,100}\b(?:receipts?|records?|requests?|enquir(?:y|ies)|inquir(?:y|ies)|data|submissions?|database|storage|confirmations?)\b|\b(?:receipts?|records?|requests?|enquir(?:y|ies)|inquir(?:y|ies)|data|submissions?)\b[^。；;\n]{0,100}\b(?:saved|stored|recorded|written|preserved|retained|archived|persist(?:s|ed|ing|ence)?)\b|\bpersist(?:s|ed|ing|ence)?\b|保存|持久|落库|写入|存储|留存/iu;
const READBACK = /\b(?:read\s*back|retriev(?:e[sd]?|able|ing)|quer(?:y|ies|ied|ying)|re-?load(?:s|ed|ing)?|refresh(?:es|ed|ing)?)\b|回读|重新读取|可查询|重新加载|刷新/iu;
const RESTART = /\b(?:re-?start(?:s|ed|ing)?|reboot(?:s|ed|ing)?)\b|重启|重新启动/iu;
const RECORD_CONTEXT = /\b(?:receipts?|records?|data|database|enquir(?:y|ies)|inquir(?:y|ies)|submissions?)\b|回执|记录|数据|保存|落库/iu;
const SOURCE_ACTION = /\b(?:page|website|source|copy|text|content|HTML)\b[^。；;\n]{0,100}\b(?:list|state|say|include|show|display|contain|identify)\b|(?:页面|网页|网站|源码|文案|文本|文字)[^。；;\n]{0,60}(?:显示|列出|包含|写明|说明|注明)/iu;

function validSource(source: unknown): source is string {
  return typeof source === "string" && !!source.trim() && source.length <= 3000 && !CONTROL.test(source)
    && ![...source].some(char => {const point = char.codePointAt(0)!; return point >= 0xd800 && point <= 0xdfff;});
}
function state(kind: AssessmentObligationKind): AssessmentObligationState {
  return kind === "source_content" ? "source_review_required" : kind === "unclassified" ? "needs_clarification" : "execution_not_verified";
}
function atomicCopy(source: string): boolean {
  return exactCopyLiteral(source) !== undefined || sourceLiteralDirective(source) !== undefined || staticMarkupDirective(source) !== undefined;
}
function withoutQuotedData(source: string): string {
  const output = source.split("");
  const pairs: Record<string, string> = {'"': '"', "'": "'", "“": "”", "「": "」"};
  for (let index = 0; index < source.length; index++) {
    const close = pairs[source[index]];
    if (!close || source[index] === "'" && /[\p{L}\p{N}]/u.test(source[index - 1] ?? "")) continue;
    let end = index + 1;
    for (; end < source.length; end++) {
      if (source[end] !== close) continue;
      let slashes = 0; for (let previous = end - 1; previous > index && source[previous] === "\\"; previous--) slashes++;
      if (slashes % 2 === 0) break;
    }
    if (end === source.length) continue;
    for (let cursor = index; cursor <= end; cursor++) output[cursor] = " ";
    index = end;
  }
  return output.join("");
}
function englishSentenceEnd(source: string, index: number): boolean {
  if (source[index] !== "." || !/^\s+[A-Z]/u.test(source.slice(index + 1))) return false;
  const token = /[^\s]+$/u.exec(source.slice(0, index + 1))?.[0] ?? "";
  const bare = token.replace(/^[([{]+/u, "").replace(/\.$/u, "");
  if (/^(?:mr|mrs|ms|dr|prof|sr|jr|st|vs|etc|e\.g|i\.e|no|fig|inc|ltd|co|u\.s|u\.k|a\.m|p\.m|approx|dept|ref|vol|ed|rev|est)$/iu.test(bare) || /^[A-Z]$/u.test(bare)) return false;
  // Dotted numbers/identifiers, email addresses and URLs are not sentence
  // witnesses. Unfamiliar punctuation remains joined and explicitly bounded.
  if (/[.@/\\]/u.test(bare) || /\d[.,]\d/u.test(bare)) return false;
  return true;
}
function clausesFor(source: string): AssessmentObligations["clauses"] {
  if (atomicCopy(source)) return [{start: 0, end: source.length, excerpt: source}];
  const result: AssessmentObligations["clauses"] = [];
  let start = 0;
  const detected = withoutQuotedData(source);
  // Split a finite English sentence form, while retaining complete original
  // sentences, negations/conditions and exact UTF-16 spans. Quoted data and
  // conjunctions/commas are not clause delimiters.
  for (let end = 1; end <= source.length; end++) {
    if (end !== source.length && !/[;；。\n]/u.test(detected[end - 1]) && !englishSentenceEnd(detected, end - 1)) continue;
    if (source.slice(start, end).trim()) result.push({start, end, excerpt: source.slice(start, end)});
    else if (result.length) {result[result.length - 1].end = end; result[result.length - 1].excerpt = source.slice(result[result.length - 1].start, end);}
    start = end;
  }
  if (result.length && result[0].start > 0) {result[0].start = 0; result[0].excerpt = source.slice(0, result[0].end);}
  return result;
}
function kindsFor(source: string): AssessmentObligationKind[] {
  if (atomicCopy(source)) return ["source_content"];
  const detected = withoutQuotedData(source);
  const kinds: AssessmentObligationKind[] = [];
  if (SUBMISSION.test(detected.toLowerCase())) kinds.push("submission");
  if (EMAIL.test(detected)) kinds.push("email_delivery");
  if (WRITE.test(detected)) kinds.push("durable_write");
  const restart = RESTART.test(detected) && RECORD_CONTEXT.test(detected);
  if (READBACK.test(detected) && !restart) kinds.push("readback");
  if (restart) kinds.push("restart_readback");
  if (kinds.length && SOURCE_ACTION.test(detected)) kinds.push("source_content");
  if (!kinds.length) kinds.push(assessmentEvidenceScope({id: "coverage-1", title: "Original requirement", source: detected}).category === "source_text" ? "source_content" : "unclassified");
  return kinds;
}

/** Frozen v1 finite detector. It neither rewrites the locked parent nor judges
 * whether any operation succeeded. New execution/report mappings need a new
 * named schema; do not retrofit inferred successes into these source records.
 * Titles and model prose are intentionally not inputs. */
export function deriveAssessmentObligations(criterion: Pick<ProofCriterion, "source">): AssessmentObligations {
  const source = criterion.source;
  if (!validSource(source)) throw new TypeError("A bounded complete locked requirement is required.");
  let clauses = clausesFor(source);
  let entries = clauses.flatMap((clause, clauseIndex) => kindsFor(clause.excerpt).map(kind => ({kind, clauseIndex})));
  if (clauses.length > LIMIT || entries.length > LIMIT) {
    // Keep all original bytes and ask for clarification, rather than silently
    // dropping an operation or an over-limit tail of the agreement.
    clauses = [{start: 0, end: source.length, excerpt: source}];
    entries = [{kind: "unclassified", clauseIndex: 0}];
  }
  return {schema: "source-obligations-v1", coverage: "bounded_detection", sourceLength: source.length, clauses,
    items: entries.map((entry, index) => ({id: `obligation-${index + 1}`, ...entry, state: state(entry.kind)}))};
}

function plainData(value: unknown): boolean {
  let nodes = 0, characters = 0;
  const ancestors = new Set<object>();
  const visit = (entry: unknown, depth: number): boolean => {
    if (++nodes > 600 || depth > 7) return false;
    if (typeof entry === "string") return (characters += entry.length) <= 16000;
    if (typeof entry === "number") return Number.isSafeInteger(entry);
    if (!entry || typeof entry !== "object" || ancestors.has(entry)) return false;
    const keys = Reflect.ownKeys(entry), array = Array.isArray(entry), prototype = Object.getPrototypeOf(entry);
    if (array ? prototype !== Array.prototype : ![Object.prototype, null].includes(prototype)) return false;
    if (array && (entry.length > 50 || keys.length !== entry.length + 1)) return false;
    ancestors.add(entry);
    for (const key of keys) {
      if (array && key === "length") continue;
      const descriptor = Object.getOwnPropertyDescriptor(entry, key)!;
      if (typeof key !== "string" || ["__proto__", "prototype", "constructor"].includes(key) || !("value" in descriptor) || !descriptor.enumerable
        || array && !/^(?:0|[1-9]\d*)$/u.test(key) || !visit(descriptor.value, depth + 1)) return false;
    }
    ancestors.delete(entry); return true;
  };
  return visit(value, 0);
}
function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
  if (value && typeof value === "object") return `{${Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`).join(",")}}`;
  return JSON.stringify(value);
}

/** Import/current/history validator. Invalid values are rejected, not repaired.
 * Re-derivation establishes binding to the supplied original wording only;
 * it does not prove an exhaustive parse, model judgment or runtime execution. */
export function isAssessmentObligations(value: unknown, criterion: Pick<ProofCriterion, "source">): value is AssessmentObligations {
  if (!plainData(value)) return false;
  try {return canonical(value) === canonical(deriveAssessmentObligations(criterion));} catch {return false;}
}

const COPY: Record<AssessmentObligationKind, {zh: [string, string]; en: [string, string]}> = {
  submission: {zh: ["提交及错误条件", "按原文核对已有提交、响应与错误记录；成功文案本身不能证明请求执行。"], en: ["Submission and error conditions", "Inspect existing submission, response and error records against the original condition. A success message alone does not prove execution."]},
  email_delivery: {zh: ["邮件执行条件", "按原文核对发送、禁止发送或送达条件及相应收件端证据；不自动发送邮件。"], en: ["Email operation conditions", "Check the required send, no-send or delivery conditions and recipient-side evidence. No email is sent automatically."]},
  durable_write: {zh: ["记录写入与留存", "按原文核对已有写入或禁止写入记录及对应数据；不把提交成功当作持久化。"], en: ["Record write and retention", "Check existing write or no-write records and the corresponding data against the original condition. Submission success does not establish persistence."]},
  readback: {zh: ["独立读取或刷新", "核对原文要求的独立读取或刷新后结果，并关联同一条数据；不自动读写后端。"], en: ["Independent readback or reload", "Inspect the required independent readback or post-reload result and bind it to the same data. No backend read or write is started automatically."]},
  restart_readback: {zh: ["重启后的记录回读", "核对原文要求的重启条件与同一记录的回读证据；源码描述不证明重启后数据仍在。"], en: ["Record readback after restart", "Inspect the required restart condition and independent readback of the same record. Source descriptions do not prove data survived a restart."]},
  source_content: {zh: ["文字或源码内容", "对照本分句原文与父项保存的源码引用核对；此分项没有独立运行或通过结论。"], en: ["Text or source content", "Compare this original clause with the parent's retained source citations. This direction has no independent execution or pass verdict."]},
  unclassified: {zh: ["尚需澄清的要求", "双方核对这段完整原文，确认检查方法与所需证据；系统没有替它补写承诺。"], en: ["Requirement needing clarification", "Review this complete original wording together and agree the check and evidence needed. No additional promise was inferred."]},
};
export function assessmentObligationPresentation(kind: AssessmentObligationKind, currentState: AssessmentObligationState, language: Language): {label: string; state: string; nextStep: string} {
  const [label, nextStep] = COPY[kind][language];
  const status = currentState === "execution_not_verified" ? ["运行尚未验证", "Execution not verified"] : currentState === "source_review_required" ? ["需核对源码建议", "Source review required"] : ["需澄清", "Clarification needed"];
  return {label, nextStep, state: status[language === "zh" ? 0 : 1]};
}

import type {Language, ProofAssessment, ProofAssessmentItem, ProofAssessmentWithheldRisks, ProofCriterion} from "./contracts.ts";
import {assertStaticPath, staticFileKind} from "./static-resources.ts";
import {createSourcePresenceEvidenceCheck} from "./source-presence-evidence.ts";

/** Independently re-derive this finite scope from exact locked criteria and
 * matching item identities; a caller/model boolean is never an authority. */
function htmlPath(value: string): boolean {try {return assertStaticPath(value) === value && staticFileKind(value) === "html";} catch {return false;}}
function structuralCriterion(criterion: ProofCriterion): boolean {
  if (criterion.id === "mobile") return ["All delivered pages must be usable on a mobile screen; a person must check them directly.", "所有交付页面都必须能在手机屏幕上正常使用；必须由人实际检查。"].includes(criterion.source);
  if (/^page-(?:[1-9]|10)$/u.test(criterion.id)) {
    const page = /^Deliver (\S+) as a separate nonempty HTML document with an HTML doctype, a nonempty title and a body\.$/u.exec(criterion.source)
      ?? /^交付独立非空 HTML 文档 ([^，\s]+)，包含 HTML doctype、非空 title 与 body。$/u.exec(criterion.source);
    return !!page && htmlPath(page[1]);
  }
  if (/^link(?:-[2-5])?$/u.test(criterion.id)) {
    const link = /^(\S+) contains a link labelled “([^\r\n]{1,120})” pointing to (\S+)\.$/u.exec(criterion.source)
      ?? /^([^\s]+) 包含文字为“([^\r\n]{1,120})”的链接，指向 ([^\s]+)。$/u.exec(criterion.source);
    if (!link || !htmlPath(link[1])) return false;
    const target = /^([^#]+\.html)(?:#[A-Za-z0-9_][A-Za-z0-9_.:-]{0,127})?$/iu.exec(link[3]);
    return !!target && htmlPath(target[1]);
  }
  return false;
}
/** Only named production structural criteria may accompany the explicit
 * contact-copy subset. Ignoring another custom obligation would be a scope bug.
 * This does not establish that any structural or content item passed. */
export function finiteContactPresenceScopeCriterionIds(criteria: readonly ProofCriterion[] | undefined, items: readonly Pick<ProofAssessmentItem, "criterionId">[], files: Record<string, string>): string[] | undefined {
  if (!Array.isArray(criteria) || criteria.length < 1 || criteria.length > 33 || criteria.length !== items.length
    || new Set(criteria.map(criterion => criterion?.id)).size !== criteria.length) return;
  const check = createSourcePresenceEvidenceCheck(files);
  const ids: string[] = [];
  for (const [index, criterion] of criteria.entries()) {
    if (!criterion || typeof criterion.id !== "string" || criterion.id !== items[index]?.criterionId || typeof criterion.source !== "string" || criterion.source.length > 3000) return;
    if (/^(?:manual-[1-5]|coverage-(?:[1-9]|1[0-2]))$/u.test(criterion.id)) {
      if (check(criterion).kind === "not_applicable") return;
      ids.push(criterion.id);
    } else if (!structuralCriterion(criterion)) return;
  }
  return ids.length ? ids : undefined;
}

/** Semantic publication policy, after the caller has validated every model
 * item/risk field and exact citation. This is not malformed-response recovery:
 * it never supplies a missing risk field or relaxes an earlier rejection.
 * Model limitation prose is intentionally unavailable here: only its count may
 * inform a fixed system note, never become a verified detection fact. */
export function publishSourceAssessmentNotes(
  language: Language,
  items: readonly ProofAssessmentItem[],
  originalStatuses: ReadonlyMap<string, string>,
  risks: ProofAssessment["risks"],
  modelLimitationCount: number,
  files: Record<string, string>,
  criteria?: readonly ProofCriterion[],
): {risks: ProofAssessment["risks"]; limitations: string[]; statusAdjustedCount: number; withheldRisks?: ProofAssessmentWithheldRisks} {
  if (!Number.isSafeInteger(modelLimitationCount) || modelLimitationCount < 0) throw new TypeError("Source publication needs a nonnegative model-limitation count.");
  if (risks.length > 5) throw new TypeError("Source publication needs at most five validated optional risks.");
  const counts = {html: 0, css: 0, raster: 0};
  for (const file of Object.keys(files)) {
    const kind = staticFileKind(file);
    if (kind === "html" || kind === "css") counts[kind]++;
    else if (kind === "png" || kind === "jpeg" || kind === "webp") counts.raster++;
  }
  const zh = language === "zh";
  const limitations = [
    zh
      ? `已提供文件清单：HTML ${counts.html} 个、CSS ${counts.css} 个、栅格图片 ${counts.raster} 个。数量只说明文件已提供。本次源码评估未运行浏览器、脚本或后台，也未分析图片像素。`
      : `Supplied inventory: ${counts.html} HTML, ${counts.css} CSS and ${counts.raster} raster image file(s). Counts establish supplied files only. This source assessment did not run a browser, scripts or backend, or analyze image pixels.`,
    zh
      ? `模型提供了 ${modelLimitationCount} 条自述局限；其中事实未经独立核验，未作为检测事实发布。请以逐项证据和系统边界说明为准。`
      : `The model supplied ${modelLimitationCount} self-described limitations; their facts were not independently verified, so they are not published as detection findings. Use item evidence and system boundaries.`,
  ];
  const statuses = ["supported", "changes_suggested", "insufficient_evidence"] as const;
  const status = (value: string | undefined): value is ProofAssessmentItem["status"] => statuses.some(candidate => candidate === value);
  if (items.length > 33 || new Set(items.map(item => item.criterionId)).size !== items.length) throw new TypeError("Source publication needs bounded unique criterion identities.");
  const adjustedCriteria: ProofAssessmentWithheldRisks["adjustedCriteria"] = [];
  for (const item of items) {
    const originalStatus = originalStatuses.get(item.criterionId);
    if (!status(originalStatus) || !status(item.status)) throw new TypeError("Source publication needs each exact validated original and published status.");
    if (item.status !== originalStatus) adjustedCriteria.push({criterionId: item.criterionId, originalStatus, publishedStatus: item.status});
  }
  const statusAdjustedCount = adjustedCriteria.length;
  if (statusAdjustedCount) {
    limitations.push(zh
      ? `${statusAdjustedCount} 项状态经系统调整，${risks.length} 条未复核风险暂不采纳，以逐项证据为准。这是发布范围限制，不代表验收、授权或付款。`
      : `${statusAdjustedCount} item status(es) were adjusted by system checks. ${risks.length} unreviewed optional AI risk(s) are temporarily withheld; use item-level evidence. This publication gate does not accept work, authorize or trigger payment.`);
    const withheldRisks: ProofAssessmentWithheldRisks = {version: 1, reason: "item_status_adjusted", adjustedCriteria,
      entries: risks.map((risk, originalRiskIndex) => ({originalRiskIndex, risk: {...risk, citations: risk.citations.map(citation => ({...citation}))}}))};
    return {risks: [], limitations, statusAdjustedCount, withheldRisks};
  }
  const scopeCriterionIds = risks.length ? finiteContactPresenceScopeCriterionIds(criteria, items, files) : undefined;
  if (scopeCriterionIds) {
    limitations.push(zh
      ? `${risks.length} 条可选模型线索的独立约定范围尚未建立，已按电话／邮箱文字自定义范围单独暂缓；所有逐项结论保持不变，也未认定其他页面、链接或手机要求通过。没有伪造状态调整记录；人工意见不自动解除暂缓、验收或付款。`
      : `The independent agreed scope of ${risks.length} optional model indication(s) is not established, so originals are withheld under the custom phone/email text scope. All item findings are unchanged; other page, link or mobile requirements are not declared passed. No status-adjustment record was invented. Human opinions do not release the gate, accept work or make a payment.`);
    return {risks: [], limitations, statusAdjustedCount,
      withheldRisks: {version: 2, reason: "source_scope_unestablished", scopeCriterionIds, adjustedCriteria: [],
        entries: risks.map((risk, originalRiskIndex) => ({originalRiskIndex, risk: {...risk, citations: risk.citations.map(citation => ({...citation}))}}))}};
  }
  // Independent copies prevent later presentation edits from mutating the raw
  // validated response. Retained risks remain AI leads awaiting human review;
  // neither their presence nor this publication decision changes item status.
  return {risks: risks.map(risk => ({...risk, citations: risk.citations.map(citation => ({...citation}))})), limitations, statusAdjustedCount,
    withheldRisks: {version: 1, reason: "not_withheld", adjustedCriteria: [], entries: []}};
}

import {ProviderError} from "./providers.ts";
import {ASSESSMENT_ITEM_CITATION_LIMIT} from "./assessment-limits.ts";

export type AssessmentFailureReason = "structure" | "output_limit" | "incomplete" | "citation" | "missing_items" | "duplicate_items" | "unknown_items" | "risk_fields";
export type AssessmentCoverageDiagnostic = {
  expectedCriterionIds: readonly string[];
  missingCriterionIds: readonly string[];
  duplicateCriterionIds: readonly string[];
  unknownCriterionCount: number;
};
const MESSAGES: Record<AssessmentFailureReason, string> = {
  structure: "AI returned an invalid response structure.",
  output_limit: "AI output reached the configured response limit and is incomplete.",
  incomplete: "AI returned an incomplete response.",
  citation: "AI source citation validation failed; a quotation or file was not found in the supplied source.",
  missing_items: "AI omitted one or more required criterion responses.",
  duplicate_items: "AI repeated one or more criterion responses.",
  unknown_items: "AI returned responses for criteria outside the confirmed checklist.",
  risk_fields: "An AI risk entry has missing or invalid detail fields.",
};
/** Safe machine-readable diagnostics only. Unknown model IDs and model text are
 * never attached; known IDs come exclusively from the validated locked input. */
export class AssessmentResponseError extends ProviderError {
  readonly reason: AssessmentFailureReason;
  readonly coverage?: AssessmentCoverageDiagnostic;
  constructor(reason: AssessmentFailureReason, coverage?: AssessmentCoverageDiagnostic) {
    super(`${MESSAGES[reason]} The saved rules and buyer decisions remain unchanged.`);
    this.reason = reason;
    if (coverage) this.coverage = Object.freeze({
      expectedCriterionIds: Object.freeze([...coverage.expectedCriterionIds]),
      missingCriterionIds: Object.freeze([...coverage.missingCriterionIds]),
      duplicateCriterionIds: Object.freeze([...coverage.duplicateCriterionIds]),
      unknownCriterionCount: coverage.unknownCriterionCount,
    });
  }
}
const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u;
const IDENTIFIER = /^[A-Za-z0-9_-]{1,80}$/u;
const ITEM_KEYS = ["criterionId", "status", "explanation", "citations"] as const;
function fail(): never {throw new AssessmentResponseError("structure");}
function shell(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value) || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) fail();
  const r = value as Record<string, unknown>;
  if (Reflect.ownKeys(r).length !== ITEM_KEYS.length || ITEM_KEYS.some(key => !Object.hasOwn(r, key)) || Reflect.ownKeys(r).some(key => typeof key !== "string" || !ITEM_KEYS.includes(key as typeof ITEM_KEYS[number]) || !("value" in Object.getOwnPropertyDescriptor(r, key)!))) fail();
  if (typeof r.criterionId !== "string" || !r.criterionId.trim() || r.criterionId.length > 80 || CONTROL.test(r.criterionId)
    || typeof r.status !== "string" || !["supported", "changes_suggested", "insufficient_evidence"].includes(r.status)
    || typeof r.explanation !== "string" || !r.explanation.trim() || r.explanation.length > 600 || CONTROL.test(r.explanation)
    || !Array.isArray(r.citations) || r.citations.length > ASSESSMENT_ITEM_CITATION_LIMIT) fail();
  return r;
}

/** Coverage classification follows valid item shells and ID uniqueness. This
 * rejects the complete response; it does not salvage or fabricate partial items. */
export function requireAssessmentItemCoverage(value: unknown, trustedExpectedIds: readonly string[]): Record<string, unknown>[] {
  if (!Array.isArray(trustedExpectedIds) || !trustedExpectedIds.length || trustedExpectedIds.length > 33 || trustedExpectedIds.some(id => typeof id !== "string" || !IDENTIFIER.test(id)) || new Set(trustedExpectedIds).size !== trustedExpectedIds.length || !Array.isArray(value) || value.length > 33) fail();
  const items = value.map(shell), known = new Set(trustedExpectedIds), counts = new Map<string, number>(); let unknown = 0;
  for (const item of items) {const id = item.criterionId as string; if (known.has(id)) counts.set(id, (counts.get(id) ?? 0) + 1); else unknown++;}
  const coverage: AssessmentCoverageDiagnostic = {
    expectedCriterionIds: [...trustedExpectedIds],
    missingCriterionIds: trustedExpectedIds.filter(id => !counts.has(id)),
    duplicateCriterionIds: trustedExpectedIds.filter(id => (counts.get(id) ?? 0) > 1),
    unknownCriterionCount: unknown,
  };
  if (coverage.duplicateCriterionIds.length) throw new AssessmentResponseError("duplicate_items", coverage);
  if (unknown) throw new AssessmentResponseError("unknown_items", coverage);
  if (coverage.missingCriterionIds.length) throw new AssessmentResponseError("missing_items", coverage);
  return items;
}

import {AssessmentResponseError} from "./assessment-response.ts";

const REQUIRED = ["title", "explanation", "suggestion", "citations"] as const;
const fail = ():never => {throw new AssessmentResponseError("risk_fields");};

/** A narrow compatibility rule for provider annotations with no value. Every
 * required field must be an own data property. Never supplies a missing value,
 * discards a risk, accepts non-null extras or executes a property accessor. The
 * caller still validates every required value, size and source quotation. */
export function canonicalAssessmentRisk(value:unknown):{fields:Record<string,unknown>;ignoredNullFields:number}{
 if(!value||typeof value!=="object"||Array.isArray(value)||![Object.prototype,null].includes(Object.getPrototypeOf(value)))return fail();
 const keys=Reflect.ownKeys(value);
 if(keys.length>REQUIRED.length+2||keys.some(key=>typeof key!=="string"))return fail();
 const fields:Record<string,unknown>={};
 for(const key of REQUIRED){
  const descriptor=Object.getOwnPropertyDescriptor(value,key);
  if(!Object.hasOwn(value,key)||!descriptor||!("value" in descriptor))return fail();
  fields[key]=descriptor.value;
 }
 let ignoredNullFields=0;
 for(const key of keys){
  if(REQUIRED.includes(key as typeof REQUIRED[number]))continue;
  const descriptor=Object.getOwnPropertyDescriptor(value,key);
  if(!descriptor||!("value" in descriptor)||descriptor.value!==null)return fail();
  ignoredNullFields++;
 }
 return{fields,ignoredNullFields};
}

import {DomainError} from "./domain.ts";
import {validateBookingPolicy,type BookingPartyPolicy,type BookingPolicySource} from "./booking-policy.ts";

export type BookingSlotCapacity={criterionId:string;maxGuestsPerSlot:number;source:BookingPolicySource};
export type BookingCapacityPlan={protocol:"booking-http-v3"|"booking-http-v4";criterionId:string;source:BookingPolicySource;policy:BookingPartyPolicy;slotCapacity:BookingSlotCapacity};
export type SlotCapacityProposal=Pick<BookingSlotCapacity,"maxGuestsPerSlot"|"source">;

const CONTROL_OR_FORMAT=/[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2066-\u2069]/u;
const IDENTIFIER=/^[A-Za-z0-9][A-Za-z0-9_-]{0,79}$/u;
function object(value:unknown,allowed:readonly string[],name:string):Record<string,unknown>{
  if(!value||typeof value!=="object"||Array.isArray(value)||![Object.prototype,null].includes(Object.getPrototypeOf(value)))throw new DomainError(`${name} must be a plain object.`);
  for(const key of Reflect.ownKeys(value))if(typeof key!=="string"||!allowed.includes(key)||!("value"in Object.getOwnPropertyDescriptor(value,key)!))throw new DomainError(`${name} contains an unsupported field.`);
  return value as Record<string,unknown>;
}
function identifier(value:unknown,name:string):string{
  if(typeof value!=="string"||!IDENTIFIER.test(value))throw new DomainError(`${name} is invalid.`);return value;
}
function exactSource(value:unknown,name:string):BookingPolicySource{
  const source=object(value,["start","end","excerpt"],name);
  if(!Number.isSafeInteger(source.start)||!Number.isSafeInteger(source.end)||(source.start as number)<0||(source.end as number)<=(source.start as number)
    ||typeof source.excerpt!=="string"||!source.excerpt.trim()||source.excerpt.length>1000||CONTROL_OR_FORMAT.test(source.excerpt)
    ||(source.end as number)-(source.start as number)!==source.excerpt.length)throw new DomainError(`${name} must retain an exact complete UTF-16 source clause.`);
  return{start:source.start as number,end:source.end as number,excerpt:source.excerpt};
}
const ENGLISH_UPPER_BOUND=String.raw`(?:at\s+most|no\s+more\s+than|up\s+to|a\s+max(?:imum)?\s+of)`;
const ENGLISH_SLOT_VERB=String.raw`(?:accepts|allows|supports|holds|accommodates|(?:can|may)\s+(?:accept|allow|support|hold|accommodate))`;
// The subject must still be a whole time slot, never "guests per booking".
// An optional "in total" cannot hide a trailing exception or another policy.
const GRAMMARS=[
  new RegExp(String.raw`^(?:each|every)\s+(?:time\s+)?slot\s+${ENGLISH_SLOT_VERB}\s+${ENGLISH_UPPER_BOUND}\s+([1-9]\d?)\s+(?:people|persons|guests)(?:\s+in\s+total)?$`,"iu"),
  /^(?:the\s+)?max(?:imum)?\s+(?:total\s+)?(?:guest\s+)?capacity\s+(?:per|for\s+each)\s+(?:time\s+)?slot(?:\s+is|\s*:)\s*([1-9]\d?)\s+(?:people|persons|guests)$/iu,
  /^每(?:个|個|一|一個)?(?:时间段|时段|時間段|時段)(?:的)?(?:合计|合計|总共|總共|总计|總計|总|總)?(?:人数|人數|容量)?(?:(?:最多|至多)(?:可)?(?:接受|接待|容纳|容納)?|(?:不|不得|不能)超(?:过|過)|上限(?:为|是|為)?)\s*([1-9]\d?)\s*(?:人|位客人)(?:合计|合計|总计|總計)?$/u,
] as const;

/** A narrow complete-clause proposal. The original span, including punctuation,
 * remains intact: no convenient substring can discard an exception or minimum. */
export function suggestSlotCapacity(requirementSource:unknown):SlotCapacityProposal|undefined{
  const source=exactSource(requirementSource,"Slot-capacity requirement");
  const clause=source.excerpt.trim().replace(/[。.!！]$/u,"").trimEnd();
  for(const grammar of GRAMMARS){
    const match=grammar.exec(clause);if(!match)continue;
    const maxGuestsPerSlot=Number(match[1]);
    if(maxGuestsPerSlot<3||maxGuestsPerSlot>12)return;
    return{maxGuestsPerSlot,source};
  }
}
export function validateSlotCapacity(value:unknown,requirementSource:unknown):SlotCapacityProposal{
  const raw=object(value,["maxGuestsPerSlot","source"],"Slot capacity"),source=exactSource(raw.source,"Slot-capacity source");
  const proposed=suggestSlotCapacity(requirementSource);
  if(!proposed||raw.maxGuestsPerSlot!==proposed.maxGuestsPerSlot||source.start!==proposed.source.start||source.end!==proposed.source.end||source.excerpt!==proposed.source.excerpt)
    throw new DomainError("Slot capacity must match one complete supported original clause and its exact source span.");
  return proposed;
}

/** The atomic-capacity recipe deliberately supports only a small range where
 * two individually valid requests exceed one slot and a positive fill remains. */
export function capacityRecipeNumbers(plan:BookingCapacityPlan):{maxPartySize:number;maxGuestsPerSlot:number;racePartySize:number;remainingPartySize:number}{
  const maxPartySize=plan.policy.maxPartySize,maxGuestsPerSlot=plan.slotCapacity.maxGuestsPerSlot;
  if(!Number.isInteger(maxPartySize)||maxPartySize<2||maxPartySize>12||!Number.isInteger(maxGuestsPerSlot)||maxGuestsPerSlot<3||maxGuestsPerSlot>12
    ||maxPartySize>maxGuestsPerSlot||maxGuestsPerSlot>=2*maxPartySize)throw new DomainError("Capacity checks require party maximum M2–12, slot maximum C3–12 and M ≤ C < 2M.");
  const racePartySize=Math.floor(maxGuestsPerSlot/2)+1,remainingPartySize=maxGuestsPerSlot-racePartySize;
  return{maxPartySize,maxGuestsPerSlot,racePartySize,remainingPartySize};
}

/** Caller-provided criteria must already be the included agreement criteria.
 * Root intake additionally resolves the capacity clause against saved coverage. */
export function validateBookingCapacityPlan(value:unknown,options:{sourceText?:string;criteria?:{id:string;source?:string}[]}={}):BookingCapacityPlan{
  const raw=object(value,["protocol","criterionId","source","policy","slotCapacity"],"Capacity test plan");
  if(raw.protocol!=="booking-http-v3"&&raw.protocol!=="booking-http-v4")throw new DomainError("Choose the explicit booking-http-v3 or booking-http-v4 capacity protocol.");
  const criterionId=identifier(raw.criterionId,"Party-limit criterion"),source=exactSource(raw.source,"Party-limit source");
  const policy=validateBookingPolicy(raw.policy,source),capacity=object(raw.slotCapacity,["criterionId","maxGuestsPerSlot","source"],"Slot-capacity criterion");
  const capacityId=identifier(capacity.criterionId,"Slot-capacity criterion"),capacitySource=exactSource(capacity.source,"Complete slot-capacity source");
  if(capacityId===criterionId||!(source.end<=capacitySource.start||capacitySource.end<=source.start))throw new DomainError("Party and slot limits need two separate included original clauses.");
  const proposed=validateSlotCapacity({maxGuestsPerSlot:capacity.maxGuestsPerSlot,source:capacitySource},capacitySource);
  for(const[id,clause]of[[criterionId,source],[capacityId,capacitySource]] as const){
    if(options.sourceText!==undefined&&options.sourceText.slice(clause.start,clause.end)!==clause.excerpt)throw new DomainError("Capacity sources must retain the exact original requirement substrings.");
    if(options.criteria){const criterion=options.criteria.find(item=>item.id===id);if(!criterion||criterion.source!==undefined&&criterion.source!==clause.excerpt)throw new DomainError("Capacity sources must match separate included original criteria.");}
  }
  const plan:BookingCapacityPlan={protocol:raw.protocol,criterionId,source,policy,slotCapacity:{criterionId:capacityId,...proposed}};
  capacityRecipeNumbers(plan);return plan;
}

import { DomainError } from "./domain.ts";

export type BookingPolicySource = { start: number; end: number; excerpt: string };
export type BookingPartyPolicy = { maxPartySize: number; source: BookingPolicySource };

const CONTROL_OR_FORMAT = /[\u0000-\u001f\u007f\u200b-\u200f\u202a-\u202e\u2066-\u2069]/u;
const MINIMUM = 2;
const MAXIMUM = 12;

function plain(value: unknown, name: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)
    || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) {
    throw new DomainError(`${name} must be a plain object.`);
  }
  return value as Record<string, unknown>;
}

function source(value: unknown, name: string): BookingPolicySource {
  const item = plain(value, name);
  if (Object.keys(item).some(key => !["start", "end", "excerpt"].includes(key))
    || !Number.isSafeInteger(item.start) || !Number.isSafeInteger(item.end)
    || (item.start as number) < 0 || (item.end as number) <= (item.start as number)
    || typeof item.excerpt !== "string" || !item.excerpt.trim() || item.excerpt.length > 1000
    || CONTROL_OR_FORMAT.test(item.excerpt) || (item.end as number) - (item.start as number) !== item.excerpt.length) {
    throw new DomainError(`${name} must retain an exact UTF-16 source span.`);
  }
  return { start: item.start as number, end: item.end as number, excerpt: item.excerpt };
}

/** Deliberately narrow complete-clause grammars. A value elsewhere in a clause,
 * a minimum, alternative limits, negatives or a compound sentence is not a
 * proposal. Unsupported wording remains a requirement for manual clarification.
 * These rules never infer a price, capacity/inventory rule or deployment policy.
 * Synonyms are slots in an anchored grammar, not text substitutions: "no more
 * than" is a positive upper bound only inside one of these complete clauses. */
const ENGLISH_UPPER_BOUND = String.raw`(?:at\s+most|no\s+more\s+than|up\s+to|a\s+max(?:imum)?\s+of)`;
const ENGLISH_BOOKING_VERB = String.raw`(?:accepts|allows|supports|contains|holds|accommodates|(?:can|may)\s+(?:accept|allow|support|contain|hold|accommodate))`;
const CLAUSES = [
  /^(?:(?:每(?:笔|次|个)|单次|单笔))?(?:预约|预订)(?:的)?(?:人数)?(?:(?:最多|至多)(?:可)?(?:接受|接待|容纳)?|(?:不|不得|不能)超过|上限(?:为|是)?)\s*([1-9]\d?)\s*(?:人|位客人)$/u,
  new RegExp(String.raw`^(?:each|every|a|one|single)\s+booking\s+${ENGLISH_BOOKING_VERB}\s+${ENGLISH_UPPER_BOUND}\s+([1-9]\d?)\s+(?:people|persons|guests)$`, "iu"),
  /^(?:the\s+)?max(?:imum)?\s+party\s+size\s+(?:per\s+booking|for\s+each\s+booking)(?:\s+is|\s*:)\s*([1-9]\d?)\s+(?:people|persons|guests)$/iu,
  new RegExp(String.raw`^${ENGLISH_UPPER_BOUND}\s+([1-9]\d?)\s+(?:people|persons|guests)\s+per\s+booking$`, "iu"),
] as const;

/** A proposal is deterministic and source-grounded, not an adopted check. The
 * caller must separately obtain buyer confirmation before adding a test plan.
 * The supplied requirement must already be an included, exact original span. */
export function suggestBookingPolicy(requirementSource: unknown): BookingPartyPolicy | undefined {
  const requirement = source(requirementSource, "Booking requirement");
  const leading = requirement.excerpt.length - requirement.excerpt.trimStart().length;
  const trimmed = requirement.excerpt.trim();
  const clause = trimmed.replace(/[。.!！]$/u, "").trimEnd();
  for (const grammar of CLAUSES) {
    const match = grammar.exec(clause);
    if (!match) continue;
    const maxPartySize = Number(match[1]);
    if (!Number.isInteger(maxPartySize) || maxPartySize < MINIMUM || maxPartySize > MAXIMUM) return;
    const start = requirement.start + leading;
    return { maxPartySize, source: { start, end: start + clause.length, excerpt: clause } };
  }
  return;
}

/** Re-derive from the complete included clause, then compare the caller's value
 * and literal citation. Selecting a convenient digit from a conflicting or
 * unsupported clause cannot turn it into a supported maximum-party policy. */
export function validateBookingPolicy(value: unknown, requirementSource: unknown): BookingPartyPolicy {
  const item = plain(value, "Booking policy");
  if (Object.keys(item).some(key => !["maxPartySize", "source"].includes(key))
    || !Number.isInteger(item.maxPartySize) || (item.maxPartySize as number) < MINIMUM || (item.maxPartySize as number) > MAXIMUM) {
    throw new DomainError("Booking maximum party size must be an integer from 2 to 12.");
  }
  const proposedSource = source(item.source, "Booking policy source");
  const proposed = suggestBookingPolicy(requirementSource);
  if (!proposed || item.maxPartySize !== proposed.maxPartySize
    || proposedSource.start !== proposed.source.start || proposedSource.end !== proposed.source.end
    || proposedSource.excerpt !== proposed.source.excerpt) {
    throw new DomainError("Booking policy must match one clear maximum-party requirement and its exact source span.");
  }
  return proposed;
}

import type { ProofBusinessCheck, ProofBusinessCheckReading, ProofBusinessCheckReport, ProofBusinessCheckStep, ProofBusinessExpected, ProofQuote, StaticProjectSpec } from "./contracts.ts";
import { DomainError } from "./domain.ts";
import { validateSavedCoverage } from "./requirement-coverage.ts";

export const BUSINESS_CHECK_LIMIT = 8;
export const BUSINESS_BLOCK_LIMIT = 12;
export const BUSINESS_BLOCK_TEXT_LIMIT = 300;
const CONTROL = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u;
const REASONS = new Set(["missing_file", "load_failed", "snapshot_mismatch", "access_denied", "timeout", "navigation_changed", "ambiguous_link", "unsupported_target", "resource_limit", "ambiguous_content", "text_limit"]);

function object(value: unknown, allowed: string[], label: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value) || ![Object.prototype, null].includes(Object.getPrototypeOf(value))) throw new DomainError(`${label} must be a plain object.`);
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== "string" || !allowed.includes(key) || !("value" in Object.getOwnPropertyDescriptor(value, key)!)) throw new DomainError(`${label} contains an unsupported field.`);
  }
  return value as Record<string, unknown>;
}
function text(value: unknown, label: string, max: number): string {
  if (typeof value !== "string" || !value.trim() || value.length > max || CONTROL.test(value) || [...value].some(char => { const point = char.codePointAt(0)!; return point >= 0xd800 && point <= 0xdfff; })) throw new DomainError(`${label} needs 1–${max} valid text characters.`);
  return value.trim();
}
function expectedValue(value: unknown): ProofBusinessExpected {
  const raw = object(value, ["kind", "text", "label", "amountMinor", "currency"], "Business expectation");
  if (raw.kind === "visible_copy") {
    object(raw, ["kind", "text"], "Visible-copy expectation");
    return {kind: "visible_copy", text: text(raw.text, "Expected visible copy", 160)};
  }
  if (raw.kind === "item_price") {
    object(raw, ["kind", "label", "amountMinor", "currency"], "Item-price expectation");
    if (typeof raw.amountMinor !== "number" || !Number.isSafeInteger(raw.amountMinor) || raw.amountMinor < 0 || (raw.currency !== "AUD" && raw.currency !== "USD")) throw new DomainError("Expected price needs nonnegative safe-integer cents and AUD or USD.");
    return {kind: "item_price", label: text(raw.label, "Expected item label", 80), amountMinor: raw.amountMinor, currency: raw.currency};
  }
  throw new DomainError("Unsupported business expectation kind.");
}
function items(value: unknown, project: StaticProjectSpec): ProofBusinessCheck[] {
  if (!Array.isArray(value) || value.length > BUSINESS_CHECK_LIMIT) throw new DomainError("Use at most eight business checks.");
  if (!value.length) return [];
  if (!project.coverage) throw new DomainError("Business checks need confirmed original-requirement coverage.");
  const coverage = validateSavedCoverage(project.coverage);
  return value.map((entry, index) => {
    const row = object(entry, ["id", "criterionId", "file", "source", "expected"], "Business check");
    const id = `business-${index + 1}`;
    if (row.id !== id) throw new DomainError("Business check identifiers must be sequential business-N identifiers.");
    const criterion = coverage.decisions.find(item => item.disposition === "include" && item.criterionId === row.criterionId);
    if (!criterion) throw new DomainError("Business checks must reference an included original requirement.");
    if (typeof row.file !== "string" || !project.requiredPages.includes(row.file)) throw new DomainError("Business checks must use an agreed required HTML page.");
    const source = object(row.source, ["start", "end", "excerpt"], "Business-check original source");
    if (typeof source.start !== "number" || typeof source.end !== "number" || !Number.isSafeInteger(source.start) || !Number.isSafeInteger(source.end)
      || source.start < criterion.start || source.end > criterion.end || source.end <= source.start || typeof source.excerpt !== "string" || !source.excerpt.trim()
      || source.excerpt !== coverage.sourceText.slice(source.start, source.end)) throw new DomainError("Business source must be an exact span within its included original requirement.");
    text(source.excerpt, "Business-check source excerpt", 300);
    // Expectations are explicit buyer inputs. This parser does not infer that an
    // exact source quote semantically entails a particular price or phrase.
    return {id, criterionId: criterion.criterionId!, file: row.file, source: {start: source.start, end: source.end, excerpt: source.excerpt}, expected: expectedValue(row.expected)};
  });
}
/** New scope input requires a separate, explicit confirmation of all expected values. */
export function parseBusinessChecks(value: unknown, project: StaticProjectSpec): ProofBusinessCheck[] {
  const input = object(value, ["confirmed", "items"], "Business checks");
  if (input.confirmed !== true) throw new DomainError("Confirm all expected business values before locking the scope.");
  return items(input.items, project);
}
/** Saved arrays retain their original ordering and source bindings. */
export function validateSavedBusinessChecks(value: unknown, project: StaticProjectSpec): ProofBusinessCheck[] { return items(value, project); }

export function normalizeBusinessText(value: string): string { return value.normalize("NFKC").replace(/\s+/gu, " ").trim().toLowerCase(); }
/** Literal phrase matching, not semantic or visual correctness. Chinese phrases may occur within a sentence. */
export function containsBusinessText(haystack: string, needle: string): boolean {
  const value = normalizeBusinessText(haystack), target = normalizeBusinessText(needle);
  if (!target) return false;
  let cursor = 0;
  while (cursor <= value.length - target.length) {
    const at = value.indexOf(target, cursor);
    if (at < 0) return false;
    const before = value[at - 1] ?? "", after = value[at + target.length] ?? "";
    if (!(/[a-z0-9_]/u.test(target[0]) && /[a-z0-9_]/u.test(before)) && !(/[a-z0-9_]/u.test(target.at(-1)!) && /[a-z0-9_]/u.test(after))) return true;
    cursor = at + 1;
  }
  return false;
}
type Evaluation = {outcome: "expected_observation" | "mismatch" | "unavailable"; explanation: string};
type Money = {currency: "aud" | "usd"; amountMinor: number};
function prices(block: string): {values: Money[]; ambiguous: boolean} {
  const normalized = normalizeBusinessText(block), values: Money[] = [];
  let ambiguous = /[$€£¥₹₩₽₫฿₱₦₺₪]/u.test(normalized);
  // Only AUD/USD ISO notation is supported by this observation. An explicit
  // Chinese currency token beside a number must not disappear when another
  // ISO price is parsed, even if that ISO price happens to match. Currency
  // words inside an item name, such as 元气牛肉面, have no adjacent amount.
  const foreignCurrency = "人民币|人民幣|港元|港币|港幣|日元|日圆|日圓|欧元|歐元|澳元|澳币|澳幣|美元|美金|英镑|英鎊|加元|纽元|紐元|韩元|韓元|法郎|卢比|盧比|卢布|盧布|泰铢|泰銖|台币|台幣|臺幣|元|圆|圓";
  const foreignMoney = new RegExp(`(?:(?:${foreignCurrency})\\s*[+\\-]?\\d+(?:[.,]\\d+)?|[+\\-]?\\d+(?:[.,]\\d+)?\\s*(?:${foreignCurrency}))`, "u");
  if (foreignMoney.test(normalized)) ambiguous = true;
  const consumed: {start: number; end: number}[] = [];
  // Sentence punctuation may follow a price; decimal/thousands fragments may
  // not be treated as a smaller standalone amount.
  const pattern = /(?:(?<![a-z0-9_+\-])(aud|usd)\s*(\d+(?:\.\d+)?)(?![a-z0-9_]|[.,](?=\S))|(?<![a-z0-9_.,+\-])(\d+(?:\.\d+)?)\s*(aud|usd)(?![a-z0-9_]))/gu;
  for (const match of normalized.matchAll(pattern)) {
    consumed.push({start: match.index, end: match.index + match[0].length});
    const literal = match[2] ?? match[3], currency = (match[1] ?? match[4]) as Money["currency"];
    if (!/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/u.test(literal)) {ambiguous = true; continue;}
    const [whole, fraction = ""] = literal.split(".");
    const amountMinor = Number(whole) * 100 + Number(fraction.padEnd(2, "0"));
    if (!Number.isSafeInteger(amountMinor)) {ambiguous = true; continue;}
    values.push({currency, amountMinor});
  }
  let residual = normalized;
  for (const span of consumed.reverse()) residual = residual.slice(0, span.start) + " ".repeat(span.end - span.start) + residual.slice(span.end);
  // A second unsupported or malformed money token must not be silently
  // discarded just because another amount happens to match the expectation.
  if (/(?<![a-z])(?:aud|usd)(?![a-z])/u.test(residual)
    || /(?<![a-z])[a-z]{3}\s*\d/u.test(residual)
    || /\d+(?:\.\d+)?\s*[a-z]{3}(?![a-z])/u.test(residual)) ambiguous = true;
  return {values, ambiguous};
}
/** The result describes supplied visible blocks, never pixels, runtime behavior or a guarantee of delivery quality. */
export function evaluateBusinessBlocks(expected: ProofBusinessExpected, blocks: string[]): Evaluation {
  const normalized = [...new Set(blocks.map(normalizeBusinessText))];
  if (expected.kind === "visible_copy") return normalized.some(block => containsBusinessText(block, expected.text))
    ? {outcome: "expected_observation", explanation: "The expected literal copy was observed in a supplied visible text block."}
    : {outcome: "mismatch", explanation: "The expected literal copy was not observed in the supplied visible text blocks."};
  const matching = normalized.filter(block => containsBusinessText(block, expected.label));
  if (!matching.length) return {outcome: "mismatch", explanation: "The expected item label was not observed in a supplied visible text block."};
  const amounts = new Map<string, Money>();
  for (const block of matching) {
    const parsed = prices(block);
    if (parsed.ambiguous || !parsed.values.length) return {outcome: "unavailable", explanation: "The item block does not provide an unambiguous standalone amount with explicit AUD or USD currency."};
    for (const money of parsed.values) amounts.set(`${money.currency}:${money.amountMinor}`, money);
  }
  if (amounts.size !== 1) return {outcome: "unavailable", explanation: "The item label is associated with conflicting amounts or currencies in the supplied visible blocks."};
  const observed = [...amounts.values()][0];
  return observed.currency === expected.currency.toLowerCase() && observed.amountMinor === expected.amountMinor
    ? {outcome: "expected_observation", explanation: "The item label and expected ISO currency/amount were observed together in an unambiguous visible block."}
    : {outcome: "mismatch", explanation: `The item block reports ${observed.currency.toUpperCase()} ${(observed.amountMinor / 100).toFixed(2)}, which differs from the buyer-confirmed currency or amount.`};
}
/** The saved agreement supplies every expected value; clients submit observations only. */
export function getBusinessCheckPlan(quote: ProofQuote): ProofBusinessCheckStep[] {
  const project = quote.proof.project;
  if (project?.businessChecks === undefined) return [];
  const checks = validateSavedBusinessChecks(project.businessChecks, project);
  if (!checks.length) return [];
  if (project.coverage?.sourceText !== quote.summary.trim()) throw new DomainError("Business checks no longer match the original project summary.", 409);
  for (const check of checks) {
    const criterion = project.coverage!.decisions.find(row => row.criterionId === check.criterionId)!;
    if (!quote.proof.criteria.some(row => row.id === check.criterionId && row.source === criterion.text)) throw new DomainError("Business checks reference a missing or changed original criterion.", 409);
  }
  return checks.flatMap(({id, ...check}) => ([375, 900] as const).map(viewportWidth => ({...structuredClone(check), checkId: id, stepId: `business:${viewportWidth}:${id}`, viewportWidth})));
}
/** Complete, bounded client observations; server-derived expectations and outcomes are not independent browser verification. */
export function createBusinessCheckReport(quote: ProofQuote, value: unknown, receivedAt = new Date().toISOString()): ProofBusinessCheckReport {
  const input = object(value, ["deliveryId", "previousReportId", "readings"], "Business observations"), delivery = quote.proof.delivery;
  if (!delivery || input.deliveryId !== delivery.id) throw new DomainError("Business checks must use the current delivery version.", 409);
  if (!Object.hasOwn(input, "previousReportId") || input.previousReportId !== (delivery.businessChecks?.id ?? null)) throw new DomainError("Business observations changed. Refresh before saving another run.", 409);
  const plan = getBusinessCheckPlan(quote);
  if (!plan.length) throw new DomainError("The agreement has no buyer-confirmed business checks.", 409);
  if (!Array.isArray(input.readings) || input.readings.length !== plan.length) throw new DomainError("Business observations must cover every agreed check and width exactly once.");
  const remaining = new Map(plan.map(step => [step.stepId, step])), rows = new Map<string, ProofBusinessCheckReport["readings"][number]>();
  for (const raw of input.readings) {
    const row = object(raw, ["stepId", "status", "blocks", "reason"], "Business observation"), step = typeof row.stepId === "string" ? remaining.get(row.stepId) : undefined;
    if (!step) throw new DomainError("Unexpected or duplicate business observation step.");
    remaining.delete(step.stepId);
    let reading: ProofBusinessCheckReading, evaluation: Evaluation;
    if (row.status === "unavailable") {
      object(row, ["stepId", "status", "reason"], "Unavailable business observation");
      if (typeof row.reason !== "string" || !REASONS.has(row.reason)) throw new DomainError("Unknown business unavailability reason.");
      reading = {stepId: step.stepId, status: "unavailable", reason: row.reason as Extract<ProofBusinessCheckReading, {status: "unavailable"}>["reason"]};
      evaluation = {outcome: "unavailable", explanation: `The browser could not provide a bounded observation: ${row.reason}.`};
    } else if (row.status === "observed") {
      object(row, ["stepId", "status", "blocks"], "Observed business content");
      if (!Object.hasOwn(delivery.files ?? {}, step.file)) throw new DomainError("A missing required page cannot have observed business content.");
      if (!Array.isArray(row.blocks) || row.blocks.length > BUSINESS_BLOCK_LIMIT) throw new DomainError("Business observations may include at most 12 visible blocks.");
      const blocks = row.blocks.map(block => text(block, "Observed visible block", BUSINESS_BLOCK_TEXT_LIMIT));
      reading = {stepId: step.stepId, status: "observed", blocks};
      evaluation = evaluateBusinessBlocks(step.expected, blocks);
    } else throw new DomainError("Unsupported business observation status.");
    rows.set(step.stepId, {...step, ...reading, ...evaluation});
  }
  if (typeof receivedAt !== "string" || !Number.isFinite(Date.parse(receivedAt))) throw new DomainError("Invalid business observation receipt time.");
  const readings = plan.map(step => rows.get(step.stepId)!);
  return {id: crypto.randomUUID(), deliveryId: delivery.id, method: "client-business-content-v1", receivedAt, readings,
    summary: {steps: readings.length, observed: readings.filter(row => row.status === "observed").length, issues: readings.filter(row => row.outcome === "mismatch").length, unavailable: readings.filter(row => row.outcome === "unavailable").length}};
}

