    const originalStatuses = new Map(responseItems.map(value => {const item=record(value);return [String(item.criterionId),String(item.status)] as const;}));
    const publication: ReturnType<typeof publishSourceAssessmentNotes> = encoding === "catalog_slots"
      ? publishSourceAssessmentNotes(quote.language, items, originalStatuses, risks, modelLimitations.length, files, criteria)
      : {risks, limitations: [...modelLimitations], statusAdjustedCount: 0};
    const limitations = publication.limitations;
    limitations.push(catalog ? words(quote,
      `引文协议：source-citation-catalog-v1 / ${encoding}，目录 ${catalog.catalogId}。模型选择编号，服务器按原始文件位置还原引文；编号有效不代表判断正确。`,
      `Citation protocol: source-citation-catalog-v1 / ${encoding}, catalog ${catalog.catalogId}. The model selected IDs; the server restored exact source offsets. Valid IDs do not establish correct judgment.`) : words(quote, "历史引文协议回放：legacy_quotes。此入口仅用于明确的旧报告测试，不是当前在线协议。", "Historical citation protocol replay: legacy_quotes. This explicit old-report test path is not the active live protocol."));
    if (parsedCompletion.repairedTrailingBrace) limitations.push(words(quote,
      "源码校验记录：工具参数在完整 JSON 对象之后多出一个闭合符，仅移除了该末尾符号；未修改任何字段值，全部报告规则仍经过核对。",
      "Source validator record: removed one orphan closing brace after a complete JSON object in tool arguments. No field value was changed; every report rule was still checked."));
    if (ignoredNullRiskFields) limitations.push(words(quote,
      `源码校验记录：忽略了 ${ignoredNullRiskFields} 个额外的空值风险注释字段。全部必填风险字段和引用仍经过核对，未补造缺失建议；这不证明模型判断正确。`,
      `Source validator record: ignored ${ignoredNullRiskFields} extra null-valued risk annotation fields. All required risk fields and citations were still validated; no missing suggestion was invented. This does not establish model judgment correctness.`));
    limitations.push(words(quote, "已发送全部受支持 HTML/CSS 原文，但完整输入不代表 AI 已正确理解；未运行浏览器、脚本或后台，不能证明功能、安全性或完整交付。", "Complete supported HTML/CSS text was supplied, but complete input does not establish correct model understanding. No browser, scripts or backend were run; functionality, security and full delivery are not established."));
    limitations.push(words(quote, "AI 建议与服务端规则分开记录。人工检查和最终验收由买家完成，不会自动验收、授权或付款。", "AI suggestions are separate from server rules. The buyer completes human checks and final acceptance; no acceptance, authorization or payment is automatic."));
    if (Object.keys(files).some(file => !["html", "css"].includes(staticFileKind(file) ?? ""))) limitations.push(words(quote, "文件清单中的图片已经交付，但像素未送交 AI 分析；从文本分析范围省略不等于图片文件缺失或显示失败。", "Raster files in the inventory were delivered, but their pixels were not sent to AI. Omission from text-source coverage does not mean an image file is missing or failed to display."));
    const tokenUsage = usage(response.data.usage, outputTokenLimit, promptTokenUpperEstimate);
    return { id: crypto.randomUUID(), deliveryId: delivery.id, method: "source-ai-v1", mode: "live", model, assessedAt: new Date().toISOString(), items, risks: publication.risks, limitations, coverage, ...(publication.withheldRisks ? {withheldRisks: publication.withheldRisks} : {}), ...(tokenUsage ? { usage: tokenUsage } : {}) };
  } catch (error) {
    if (error instanceof AssessmentResponseError) throw error;
    throw failure();
  }
}

import type { BriefInput, LineItem, QuoteDraft } from "./contracts.ts";

export const MAX_TOTAL_CENTS = 100_000_000;

/** Errors safe to show to a caller; provider responses must never be passed in. */
export class DomainError extends Error {
  readonly status: number;
  readonly code: string;

  constructor(message: string, status = 400, code = "VALIDATION_ERROR") {
    super(message);
    this.name = "DomainError";
    this.status = status;
    this.code = code;
  }
}

function record(value: unknown, label: string): Record<string, unknown> {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new DomainError(`${label} must be an object.`);
  }
  return value as Record<string, unknown>;
}

function text(value: unknown, label: string, min: number, max: number): string {
  if (typeof value !== "string") throw new DomainError(`${label} must be text.`);
  const normalized = value.trim();
  if (normalized.length < min || normalized.length > max) {
    throw new DomainError(`${label} must contain ${min}–${max} characters.`);
  }
  if (/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u.test(normalized)) {
    throw new DomainError(`${label} contains unsupported control characters.`);
  }
  return normalized;
}

function number(value: unknown, label: string, min: number, max: number): number {
  if (typeof value !== "number" || !Number.isFinite(value) || value < min || value > max) {
    throw new DomainError(`${label} must be a number between ${min} and ${max}.`);
  }
  return value;
}

function hundredths(value: number, label: string): number {
  const scaled = Math.round(value * 100);
  if (Math.abs(value * 100 - scaled) > 0.0000001) {
    throw new DomainError(`${label} may have at most two decimal places.`);
  }
  return scaled;
}

export function validateBrief(value: unknown): BriefInput {
  const input = record(value, "Brief");
  if (input.currency !== "AUD" && input.currency !== "USD") {
    throw new DomainError("Currency must be AUD or USD.");
  }
  if (input.language !== "en" && input.language !== "zh") {
    throw new DomainError("Language must be en or zh.");
  }
  const hourlyRate = number(input.hourlyRate, "Hourly rate", 1, 5000);
  hundredths(hourlyRate, "Hourly rate");
  return {
    brief: text(input.brief, "Client brief", 20, 4000),
    clientName: text(input.clientName, "Client name", 0, 100) || (input.language === "zh" ? "客户" : "Client"),
    currency: input.currency,
    language: input.language,
    hourlyRate,
  };
}

function lineItems(value: unknown): LineItem[] {
  if (!Array.isArray(value) || value.length < 1 || value.length > 20) {
    throw new DomainError("A quote must contain between 1 and 20 line items.");
  }
  const identifiers = new Set<string>();
  return value.map((value, index) => {
    const item = record(value, `Line item ${index + 1}`);
    const id = text(item.id, "Line item ID", 1, 80);
    if (!/^[A-Za-z0-9_-]+$/u.test(id) || identifiers.has(id)) {
      throw new DomainError("Line item IDs must be unique letters, numbers, underscores or hyphens.");
    }
    identifiers.add(id);
    const quantity = number(item.quantity, "Quantity", 0.01, 1000);
    hundredths(quantity, "Quantity");
    const unitPriceCents = number(item.unitPriceCents, "Unit price in cents", 0, MAX_TOTAL_CENTS);
    if (!Number.isSafeInteger(unitPriceCents)) {
      throw new DomainError("Unit prices must use whole cents.");
    }
    return {
      id,
      description: text(item.description, "Line item description", 1, 300),
      quantity,
      unitPriceCents,
    };
  });
}

/** Round each line to its nearest cent, then add integer cents on the server. */
export function quoteTotal(value: readonly LineItem[]): number {
  const items = lineItems(value);
  let total = 0;
  for (const item of items) {
    const quantityHundredths = hundredths(item.quantity, "Quantity");
    const product = quantityHundredths * item.unitPriceCents;
    if (!Number.isSafeInteger(product)) throw new DomainError("Line item amount is too large.");
    total += Math.round(product / 100);
    if (!Number.isSafeInteger(total) || total > MAX_TOTAL_CENTS) {
      throw new DomainError("Quote total exceeds the maximum supported amount.");
    }
  }
  if (total < 1) throw new DomainError("Quote total must be at least one cent.");
  return total;
}

function textList(value: unknown, label: string): string[] {
  if (!Array.isArray(value) || value.length > 12) {
    throw new DomainError(`${label} must be a list of no more than 12 entries.`);
  }
  return value.map((entry) => text(entry, label, 1, 300));
}

/** Whitelist editable fields: client/model totals and payment state are discarded. */
export function validateDraft(value: unknown): QuoteDraft {
  const input = record(value, "Quote draft");
  const items = lineItems(input.lineItems);
  quoteTotal(items);
  const timelineDays = number(input.timelineDays, "Timeline in days", 1, 365);
  if (!Number.isInteger(timelineDays)) throw new DomainError("Timeline must use whole days.");
  return {
    title: text(input.title, "Quote title", 1, 120),
    summary: text(input.summary, "Quote summary", 1, 1000),
    lineItems: items,
    assumptions: textList(input.assumptions, "Assumptions"),
    questions: textList(input.questions, "Questions"),
    timelineDays,
  };
}

// This finite grammar recognises only a complete instruction to include one
// exact quoted string. A suffix, second obligation or unfamiliar wording does
// not inherit its text-only scope. The quotation is data, not an instruction
// to perform the operation that its words might describe.
const ENGLISH_DIRECTIVE = /^(?:(?:The|Our)\s+)?(?:page|website|site)\s+(?:copy|text(?:\s+content)?)\s+(?:must|should|needs?\s+to)\s+(?:include|contain|display|show)\s+the\s+exact\s+(?:wording|text|string)\s+(?:"([^"\r\n]{1,300})"|“([^“”\r\n]{1,300})”)[.!]?$/iu;
const CHINESE_DIRECTIVE = /^(?:页面|网页|网站)(?:文案|文字|文本)(?:必须|须|需要|应)(?:(?:逐字|原样)(?:包含|显示|写明)|(?:包含|显示|写明)(?:完全一致的|逐字相同的|准确的)(?:文字|文案|原文|字样))\s*[：:]?\s*(?:"([^"\r\n]{1,300})"|“([^“”\r\n]{1,300})”|「([^「」\r\n]{1,300})」)[。！]?$/u;

// Only HTML whitespace and NBSP are equivalent. Do not lowercase, fold Unicode
// compatibility characters, discard punctuation or compare paraphrases.
export const normalizeExactCopyWhitespace = (value: string): string => value.replace(/[\t\n\f\r \u00a0]+/gu, " ").trim();

export function exactCopyLiteral(source: string): string | undefined {
  const match = ENGLISH_DIRECTIVE.exec(source.trim()) ?? CHINESE_DIRECTIVE.exec(source.trim());
  const literal = match?.slice(1).find(value => value !== undefined);
  return literal && normalizeExactCopyWhitespace(literal) || undefined;
}

import { parse, type DefaultTreeAdapterTypes } from "parse5";
import type { Language, ProofCriterion } from "./contracts.ts";
import {exactCopyLiteral, normalizeExactCopyWhitespace as normalized} from "./exact-copy-directive.ts";

type Node = DefaultTreeAdapterTypes.Node;
type Element = DefaultTreeAdapterTypes.Element;
export type ExactCopyEvidence = { kind: "not_applicable" } | {
  kind: "present" | "missing" | "unknown";
  literal: string;
};
const BLOCKS = new Set(["address", "article", "aside", "blockquote", "body", "caption", "dd", "details", "dialog", "div", "dl", "dt", "fieldset", "figcaption", "figure", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "header", "hr", "li", "main", "nav", "ol", "p", "pre", "section", "summary", "table", "tbody", "td", "tfoot", "th", "thead", "tr", "ul"]);
const INERT_TEXT = new Set(["head", "title", "script", "style", "template", "noscript", "textarea", "xmp", "iframe", "noembed", "noframes", "plaintext"]);
const DYNAMIC_OR_UNSUPPORTED = new Set(["template", "noscript", "textarea", "xmp", "iframe", "frame", "frameset", "object", "embed", "slot", "noembed", "noframes", "plaintext"]);
const element = (node: Node): node is Element => "tagName" in node;
const attr = (node: Element, name: string) => node.attrs.find(row => row.name === name)?.value;
const generatedCss = (source: string) => /(?:\bcontent\s*:|@import\b|\\)/iu.test(source);

/** Snapshot static body-copy segments once. This deliberately does not render,
 * follow URLs, run scripts or establish that any text is visible. */
function bodyCopy(files: [string, string][]): { segments: string[]; uncertain: boolean } {
  const members = new Map(files), html = files.filter(([file]) => file.endsWith(".html"));
  if (!html.length || files.length > 40 || files.reduce((sum, [, value]) => sum + value.length, 0) > 262_144) return { segments: [], uncertain: true };
  let uncertain = files.some(([file, source]) => file.endsWith(".css") && generatedCss(source)), visited = 0;
  const segments: string[] = [];
  for (const [file, source] of html) {
    let parseIssue = false;
    const document = parse(source, { scriptingEnabled: true, onParseError: error => { if (error.code !== "missing-doctype") parseIssue = true; } });
    uncertain ||= parseIssue;
    const chunks: string[] = [], stack: { node: Node; insideBody: boolean; depth: number; exit?: boolean }[] = [{ node: document, insideBody: false, depth: 0 }];
    while (stack.length) {
      if (++visited > 50_000) return { segments: [], uncertain: true };
      const { node, insideBody, depth, exit } = stack.pop()!;
      if (depth > 512) return { segments: [], uncertain: true };
      if (exit) { chunks.push("\u0000"); continue; }
      if (node.nodeName === "#text") { if (insideBody) chunks.push((node as DefaultTreeAdapterTypes.TextNode).value); continue; }
      let body = insideBody;
      if (element(node)) {
        body ||= node.tagName === "body";
        if (node.namespaceURI !== "http://www.w3.org/1999/xhtml") { uncertain = true; if (body) chunks.push("\u0000"); continue; }
        if (node.tagName === "script" && !["application/json", "application/ld+json"].includes((attr(node, "type") ?? "").trim().toLowerCase())) uncertain = true;
        if (DYNAMIC_OR_UNSUPPORTED.has(node.tagName)) uncertain = true;
        if (node.attrs.some(row => /^on/iu.test(row.name)) || generatedCss(attr(node, "style") ?? "")) uncertain = true;
        if (node.tagName === "style" && "childNodes" in node && generatedCss(node.childNodes.map(child => child.nodeName === "#text" ? (child as DefaultTreeAdapterTypes.TextNode).value : "").join(""))) uncertain = true;
        if (node.tagName === "link" && (attr(node, "rel") ?? "").toLowerCase().split(/\s+/u).includes("stylesheet")) {
          try {
            const url = new URL(attr(node, "href") ?? "", `https://proof.invalid/${file}`);
            if (url.origin !== "https://proof.invalid" || url.pathname.includes("%") || !members.has(url.pathname.slice(1)) || !url.pathname.endsWith(".css")) uncertain = true;
          } catch { uncertain = true; }
        }
        // Input attributes may become displayed text; unlike ordinary img alt,
        // their absence from body text cannot establish missing page copy.
        if (node.tagName === "input" && (attr(node, "value") || attr(node, "placeholder"))) uncertain = true;
        if (INERT_TEXT.has(node.tagName)) {
          // Head still needs traversal for script and style uncertainty.
          if (node.tagName !== "head") { if (body) chunks.push("\u0000"); continue; }
        }
        if (body && node.tagName === "br") chunks.push(" ");
        if (body && BLOCKS.has(node.tagName)) { chunks.push("\u0000"); stack.push({ node, insideBody: body, depth, exit: true }); }
      }
      if ("childNodes" in node) for (let i = node.childNodes.length - 1; i >= 0; i--) stack.push({ node: node.childNodes[i], insideBody: body, depth: depth + 1 });
    }
    segments.push(...chunks.join("").split("\u0000").map(normalized).filter(Boolean));
  }
  return { segments, uncertain };
}

/** Shared uncertainty gate only; no invented exact-copy requirement and no
 * claim about presence, visibility or execution. */
export function hasUncertainSourceBodyCopy(files: Record<string, string>): boolean {
  return bodyCopy(Object.entries(files)).uncertain;
}

/** For a check explicitly bound to one saved HTML file, other pages do not
 * change that file's source-copy scope. Include only its directly linked local
 * stylesheets; imports and missing/external/unsupported sources stay uncertain.
 * This does not render the page or establish that a value is visible. */
export function hasUncertainSourceBodyCopyAtFile(files: Record<string, string>, file: string): boolean {
  const entries = Object.entries(files);
  if (!Object.hasOwn(files, file) || !file.endsWith(".html") || entries.length > 40
    || entries.reduce((sum, [, value]) => sum + value.length, 0) > 262_144) return true;
  const members = new Map<string, string>([[file, files[file]]]);
  const document = parse(files[file], {scriptingEnabled: true});
  const stack: {node: Node; depth: number}[] = [{node: document, depth: 0}];
  let visited = 0;
  while (stack.length) {
    const {node, depth} = stack.pop()!;
    if (++visited > 50_000 || depth > 512) return true;
    if (element(node)) {
      // A base URL can change relative resource resolution. Do not silently
      // resolve against the saved path when another base was declared.
      if (node.tagName === "base" && attr(node, "href") !== undefined) return true;
      if (node.tagName === "link" && (attr(node, "rel") ?? "").toLowerCase().split(/\s+/u).includes("stylesheet")) {
        try {
          const url = new URL(attr(node, "href") ?? "", `https://proof.invalid/${file}`);
          const target = url.pathname.slice(1);
          if (url.origin !== "https://proof.invalid" || url.pathname.includes("%") || !target.endsWith(".css") || !Object.hasOwn(files, target)) return true;
          members.set(target, files[target]);
        } catch { return true; }
      }
    }
    if ("childNodes" in node) for (let i = node.childNodes.length - 1; i >= 0; i--) stack.push({node: node.childNodes[i], depth: depth + 1});
  }
  return bodyCopy([...members]).uncertain;
}

/** A negative-only guard. Presence leaves a model suggestion unchanged; it never
 * establishes entailment, rendered visibility, acceptance or a new obligation. */
export function createExactCopyEvidenceCheck(files: Record<string, string>): (criterion: ProofCriterion) => ExactCopyEvidence {
  const snapshot = Object.entries(files);
  let copy: ReturnType<typeof bodyCopy> | undefined;
  return criterion => {
    const literal = exactCopyLiteral(criterion.source);
    if (!literal) return { kind: "not_applicable" };
    copy ??= bodyCopy(snapshot);
    const present = copy.segments.some(segment => segment.includes(literal));
    // Separate blocks cannot establish one phrase, but CSS might arrange them
    // together. Keep that ambiguous rather than inventing presence or absence.
    const acrossBoundaries = normalized(copy.segments.join(" ")).includes(literal) || copy.segments.join("").includes(literal);
    return { kind: present ? "present" : copy.uncertain || acrossBoundaries ? "unknown" : "missing", literal };
  };
}

export function exactCopyEvidenceExplanation(evidence: Extract<ExactCopyEvidence, { literal: string }>, language: Language): string {
  if (evidence.kind === "unknown") return language === "zh"
    ? `本项要求逐字包含“${evidence.literal}”。未在可确定的静态正文中找到该文字，但脚本、模板、其他内容来源或解析边界使缺失结论无法成立；需要补充运行或人工核对证据。`
    : `This criterion requires the exact wording "${evidence.literal}". It was not found in determinable static body text, but scripts, templates, other content sources or parsing limits prevent a missing-copy conclusion. Runtime or human evidence is needed.`;
  return language === "zh"
    ? `未在所提供 HTML 的静态正文中找到约定的逐字文案“${evidence.literal}”。这是源码文案差异，不是对实际可见性或运行结果的判断。`
    : `The agreed exact wording "${evidence.literal}" was not found in static body text of the supplied HTML. This is a source-copy mismatch, not a rendered-visibility or runtime result.`;
}

import { parse, type DefaultTreeAdapterTypes, type ParserError } from "parse5";

type Node = DefaultTreeAdapterTypes.Node;
type HtmlElement = DefaultTreeAdapterTypes.Element;
export type HtmlSourceTag = { name: string; attributes: Map<string, string>; start: number; end: number; valid: boolean };
export type HtmlSourceElement = { tag: HtmlSourceTag; inBody: boolean; hidden: boolean };
export type HtmlSourceAnchor = { tag: HtmlSourceTag; end: number; text: string; valid: boolean };
export type HtmlSourceInspection = {
  valid: boolean; finding: "pass" | "fail" | "needs_human"; title?: string;
  anchors: HtmlSourceAnchor[]; elements: HtmlSourceElement[]; styles: string[]; ambiguous: boolean;
};

const HTML_NAMESPACE = "http://www.w3.org/1999/xhtml";
const VOID = new Set(["area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"]);
// These end tags may legally be omitted. Parser recovery for other unclosed
// elements is not evidence of a correctly supplied source document.
const OPTIONAL_END = new Set(["html", "head", "body", "li", "dt", "dd", "p", "rt", "rp", "optgroup", "option", "colgroup", "thead", "tbody", "tfoot", "tr", "td", "th"]);
const INERT = new Set(["template", "noscript"]);
const TEXT_ONLY = new Set(["script", "style", "textarea", "xmp", "iframe", "noembed", "noframes", "plaintext"]);
const element = (node: Node): node is HtmlElement => "tagName" in node;

/**
 * Inspect an already bounded source file with the browser's HTML parsing rules.
 * This establishes document/anchor source presence, never full conformance,
 * rendered visibility, script behavior or the quality of a delivered website.
 */
export function inspectHtmlSource(source: string): HtmlSourceInspection {
  const errors: ParserError[] = [];
  const document = parse(source, { sourceCodeLocationInfo: true, scriptingEnabled: true, onParseError: error => errors.push(error) });
  const anchors: HtmlSourceAnchor[] = [], elements: HtmlSourceElement[] = [], styles: string[] = [];
  const represented: { start: number; end: number }[] = [], starts = new Set<number>();
  let ambiguous = errors.length > 0, title: string | undefined, titleCount = 0, nonemptyTitle = false, bodyFound = false, bodyContent = false, inertBodyContent = false;
  const span = (start: number, end: number) => { represented.push({ start, end }); };
  const textOf = (node: Node): string => {
    const pending = [node], values: string[] = [];
    while (pending.length) {
      const current = pending.pop()!;
      if (current.nodeName === "#text") { values.push((current as DefaultTreeAdapterTypes.TextNode).value); continue; }
      if (element(current) && (current.namespaceURI !== HTML_NAMESPACE || INERT.has(current.tagName) || TEXT_ONLY.has(current.tagName))) continue;
      if ("childNodes" in current) for (let index = current.childNodes.length - 1; index >= 0; index--) pending.push(current.childNodes[index]);
    }
    return values.join("");
  };
  // Iterative traversal bounds call-stack use for deeply nested uploaded files.
  const pending: { node: Node; inBody: boolean; hidden: boolean }[] = [{ node: document, inBody: false, hidden: false }];
  while (pending.length) {
    const { node, inBody, hidden } = pending.pop()!;
    const sourceLocation = node.sourceCodeLocation;
    if (!element(node)) {
      if (sourceLocation) span(sourceLocation.startOffset, sourceLocation.endOffset);
      if (node.nodeName === "#text" && inBody && (node as DefaultTreeAdapterTypes.TextNode).value.trim()) bodyContent = true;
      if ("childNodes" in node) for (let index = node.childNodes.length - 1; index >= 0; index--) pending.push({ node: node.childNodes[index], inBody, hidden });
      continue;
    }
    const name = node.tagName, location = node.sourceCodeLocation, start = location?.startTag;
    if (node.namespaceURI !== HTML_NAMESPACE || INERT.has(name)) {
      // Foreign/inert trees cannot supply HTML links, target IDs or resources.
      // Their exact source is still accounted for, so strings inside them do not
      // become fake markup or make an otherwise valid document malformed.
      if (location) span(location.startOffset, location.endOffset);
      if (start && !location?.endTag) ambiguous = true;
      if (inBody) inertBodyContent = true;
      continue;
    }
    if (start) {
      if (starts.has(start.startOffset)) ambiguous = true; // Parser-reconstructed formatting nodes.
      starts.add(start.startOffset);
      span(start.startOffset, start.endOffset);
      if (location.endTag) span(location.endTag.startOffset, location.endTag.endOffset);
      if (!VOID.has(name) && !OPTIONAL_END.has(name) && !location.endTag) ambiguous = true;
    }
    const nowInBody = inBody || name === "body";
    if (name === "body") bodyFound = true; // A standards-valid body can have omitted start/end tags.
    const attributes = new Map(node.attrs.filter(attr => !attr.namespace && !attr.prefix).map(attr => [attr.name, attr.value]));
    const tag: HtmlSourceTag | undefined = start ? {
      name, attributes, start: start.startOffset, end: start.endOffset,
      valid: !errors.some(error => error.startOffset >= start.startOffset && error.startOffset <= start.endOffset),
    } : undefined;
    const nowHidden = hidden || attributes.has("hidden") || attributes.has("inert");
    if (tag) elements.push({ tag, inBody, hidden: nowHidden });
    if (name === "base") ambiguous = true; // A base URL changes local reference meaning.
    if (name === "title") {
      titleCount++;
      nonemptyTitle ||= !!textOf(node).trim();
      if (location && start) title = source.slice(location.startOffset, location.endOffset);
